programs.sol:
"""A local grammar approximation, not a general semantic parser.

Positive cues are finite copulas, hypothetical clauses, partitive 'one of',
loop membership, and structured key/type openings. Indirect-question 'if'
and personal/relative subjects modify these cues. Other text stays near zero.
Only a short text suffix is carried, and it is reset between documents.
"""
import regex as re
from wordfreq import zipf_frequency

READS = ()
# Form: base, personal subject, relative/existential, 'it', conjunction, symbol.
BE = {
    'is':   (.134, -.046, -.184, .045, .093, -.109),
    'are':  (.034, -.163, -.092, .049, .097, 0),
    'was':  (.298, -.137, -.115, .015, .006, -.075),
    'were': (.188, -.208, -.112, -.179, .033, -.039),
    'be':   (-.139, .040, .062, .050, .088, .104),
    'been': (-.036, -.042, -.010, 0, -.010, 0),
    'being': (-.029, 0, -.083, 0, -.046, .017),
    'am':   (-.144, .179, 0, 0, .097, .038),
}
FOREIGN_BE = set('ist sind war waren est sont était été es é è são '
                 'sono sunt je jest er'.split())
UNCERTAIN = {
    'maybe': .564,
    'perhaps': .485,
    'suppose': .517,
    'probably': .179,
    'possibly': .249,
}
INDIRECT = set('check checking checks checked see seeing know knowing '
               'ask asked asking determine determining wonder wondering '
               'sure as'.split())
SELECTORS = set('one either neither any which what'.split())
QUANTIFIERS = set('many some none each both two three four several few'.split())


def predict(token, previous, text):
    w, p = token.strip().lower(), previous.strip().lower()
    # Recognize completed condition words even when split across tokens.
    if re.search(r'(если|якщо)$', text + token, re.I):
        return 1.05
    if re.search(r'jika$', text + token, re.I):
        return .8
    if (token[:1].isalpha() and previous[-1:].isalpha()
            and not re.match(r'\p{Script=Han}', token)):
        return .62 if w == 'pose' and p.endswith('sup') else -.004
    line = text.rsplit('\n', 1)[-1]
    capital = token.strip()[:1].isupper()
    unspaced = token[:1].isalnum()
    if w in BE:
        base, personal, relative, it, join, symbol = BE[w]
        value = base + .238 * capital + .08 * unspaced
        if p in {'i', 'we', 'you', 'he', 'she', 'they'}:
            value += personal
        if p in {'there', 'that', 'which', 'what', 'who'}:
            value += relative
        if p == 'it':
            value += it
        if p in {',', 'and', 'but', 'or'}:
            value += join
        if p[-1:].isdigit() or p in {')', '}', '$'}:
            value += symbol
        return value
    if w in FOREIGN_BE:
        return .22
    if w in UNCERTAIN:
        return UNCERTAIN[w]
    if w in {'如果', '如果您', '若'}:
        return .6
    if w == 'wenn':
        return .35
    if w == 'if':
        value = .438 + .238 * capital + .08 * unspaced
        if p in INDIRECT:
            value -= .501
        if p in {',', 'but', 'so', 'that', 'and'}:
            value += .415
        if p == 'else':
            value -= .334
        if p == 'only':
            value -= .231
        if p == 'even':
            value += .133
        if text and not line.strip():
            value -= .172
        return value
    if w in {'si', 'se'}:
        words = re.findall(r'[^\W\d_]+', text.lower())[-12:]
        language = max(('it', 'es', 'fr', 'pt', 'en', 'cs'),
                       key=lambda lang: sum(zipf_frequency(x, lang)
                                            for x in words)) if words else 'en'
        if w == 'se' and language == 'it':
            return .805
        if w == 'si' and language in {'it', 'fr', 'es'}:
            return .283
        return .02
    if w == 'of':
        if p in SELECTORS:
            return .715
        return .305 if p in QUANTIFIERS else -.003
    if w == 'in':
        loop = re.search(r'\bfor\s+\w+(?:\s*,\s*\w+)*\s*$', line)
        return .634 if loop else .007
    if w in {'"', "'"}:
        if re.search(r'["\']\s*,\s*$', text):
            return .474 if w == '"' else .212
        return .023
    if w in {'{"', "{'"}:
        return .198 if token.startswith(' ') else .743
    if w in {'","', "','"}:
        return .406
    if w in {':', '):'}:
        annotation = (re.search(r'\b(def|func|function|fn)\b', line)
                      and line.count('(') > line.count(')')) or re.search(
                          r'\b(const|let|var)\s+\w+\s*$', line)
        return .17 if annotation else -.006
    if w in {'function', '(function', '()'}:
        return .57 if p in {'=', ':', "',", '",'} else .047
    if w in {'==', '==='}:
        return .267
    if w in {'!=', '!==', 'equals', '∈'}:
        return .2
    if w in {'->', '=>', '::', '?:'}:
        return .074
    if not text and token.isspace():
        return -.3
    if w in {'than', 'while', 'shall', 'should'}:
        return -.06
    if w in {'could', 'may', 'what'}:
        return .06
    if w.startswith(')'):
        return -.021
    return -.004


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, text = '', ''
    else:
        previous, text = carry[1:]
    token = prefix.token_strings[-1]
    value = predict(token, previous, text)
    return (doc, token, (text + token)[-256:]), value

programs.haiku:
"""layers.1.mlp.down_proj:640 -- a 'conditional and hedging frame' detector.

What it responds to, in plain terms:
- An `if` that opens a conditional clause in running text ("..., if we ...", "But if",
  "So if"), and its Italian/Russian/Chinese/Indonesian equivalents ("se", "если",
  "якщо", "如果", "jika"), fire strongly. The `if` after a verb of checking ("check if",
  "see if", "as if", "determine if") does not, and an `if` at the start of an indented
  code line is weak.
- Hedges that open a hypothetical: "maybe", "perhaps", "suppose".
- The "of" in "one of" / "which of" / "any of" / "each of" (a choice among several).
- The opening quote of a JSON key at the start of a line, as in a tool call (`{"name": ...`).
- A copula that opens a question after "or" / "also" ("Or is it ...").
- Weak positive copulas ("was", "is", "est", "ist"), a negative value for "be" after a
  modal ("will be"), and a mild positive for "==" (equality test in code).
- Repeated middle-dot filler ("····") gives a strong negative (rare).
Everything else is 0. Values are hand-set from the component's activations on training
rows; the program only looks at the current word and the word before it.
"""

READS = ()

IF_WORDS = {"if", "если", "сли", "якщо", "如果", "jika"}
FOREIGN_IF = {"si", "se"}
COMPLEMENT_VERBS = {"check", "see", "ask", "determine", "know", "whether", "as",
                    "sure", "test", "wonder", "tell", "find"}
CLAUSE_END = {".", ",", "!", "?", ";", ":", "but", "so", "and", "that", "because",
              "(", "-", "*", "//", "#", "else", "even", "again", "then"}
HEDGES = {"maybe", "perhaps", "suppose", "pose"}
ONE_OF = {"one", "which", "any", "each", "either"}
MODALS = {"will", "may", "must", "might", "should", "can", "would", "could", "to"}
FOREIGN_COPULAS = {"est", "ist", "es", "é", "è", "sont", "sono", "je", "bist"}


def step(carry, prefix, upstream):
    if prefix.position == 0:
        return carry, 0.0
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    raw_before = prefix.token_strings[-2]
    before = raw_before.strip().lower()
    if token == "··":
        value = -1.6
    elif word in IF_WORDS:
        if before in COMPLEMENT_VERBS:
            value = 0.0
        elif raw_before.strip() == "":
            value = 0.25
        elif before in CLAUSE_END or raw_before.strip()[-1:] in ".,!?;:":
            value = 0.85
        else:
            value = 0.35
    elif word in FOREIGN_IF:
        value = 0.3
    elif word in HEDGES:
        value = 0.55
    elif word == "of" and before in ONE_OF:
        value = 0.7
    elif token == '{"':
        value = 0.85 if raw_before.endswith("\n") else 0.2
    elif word == '"' and before == '",':
        value = 0.55
    elif word in {"is", "was", "were"} and before in {"or", "also", "?"}:
        value = 0.55
    elif word == "was":
        value = 0.25
    elif word == "is" and before == "it":
        value = 0.25
    elif word in {"is", "were"}:
        value = 0.12
    elif word in FOREIGN_COPULAS:
        value = 0.11
    elif word == "==":
        value = 0.35
    elif word == "be" and before in MODALS:
        value = -0.15
    else:
        value = 0.0
    return carry, value

programs.sol:
"""Approximate a recent, nested grouping-expression signal.

Track unmatched round, square and curly brackets. Older openings fade on a
32-token timescale; curly braces from previous lines are ignored as probable blocks.
Openings contribute up to four levels. A small table gives each token role
an outside offset, an inside slope and an extra slope beyond one level.
Operators and further openings respond more than ordinary text. Four TeX
grouping commands have their own stronger response. This is a text-level
heuristic, not a full parser; lexical differences within roles are omitted.
"""
import math
from functools import lru_cache

READS = ()
# Role: outside offset, inside slope, additional nesting slope.
WEIGHTS = {
    'word': (-0.012, 0.099, 0.468),
    'number': (-0.029, 0.163, 0.533),
    'operator': (-0.021, 0.327, 0.621),
    'separator': (-0.011, 0.208, 0.711),
    'opener': (0.006, 1.368, -0.225),
    'spaced_opener': (-0.055, 0.708, 0.445),
    'closer': (-0.061, 0.021, 0.447),
    'reopen': (-0.09, 0.128, 1.098),
    'space': (-0.018, 0.193, 0.299),
    'newline': (-0.021, 0.022, 0.017),
    'tex_group': (-0.259, 0.751, 1.563),
}
TEX_GROUP = frozenset(('frac', 'sqrt', 'left', 'right'))


@lru_cache(maxsize=16384)
def token_role(text):
    t = text.strip()
    if '\n' in text or '\r' in text:
        return 'newline'
    if not t:
        return 'space'
    if any(ch in t for ch in ')]}'):
        return 'reopen' if any(ch in t for ch in '([{') else 'closer'
    if any(ch in t for ch in '([{'):
        return 'spaced_opener' if text[0].isspace() else 'opener'
    if t in {',', ';', ':', '":', "':", '=', ':=',
             '"', "'", '`', '",', "',"}:
        return 'separator'
    if t.startswith('.') or t[0] in '+-*/^=<>|&%_\\':
        return 'operator'
    if t.isdigit():
        return 'number'
    if any(ch.isalpha() for ch in t):
        return 'word'
    return 'operator'


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    pos = len(prefix.token_ids) - 1
    if carry is None or carry[0] != doc:
        stack, line, tex = [], 0, False
    else:
        _, stack, line, tex = carry
    text = prefix.token_strings[-1]
    role = token_role(text)
    if tex and text in TEX_GROUP:
        role = 'tex_group'

    depth = 0.0
    for bracket, opened, opened_line in stack:
        if bracket == '{' and opened_line != line:
            continue
        depth += math.exp(-max(0, pos - opened - 2) / 32)
    depth = min(depth, 4.0)
    offset, inside, nested = WEIGHTS[role]
    value = offset + inside * depth + nested * max(0, depth - 1)

    for ch in text:
        if ch in '([{':
            stack.append((ch, pos, line))
        elif ch in ')]}':
            match = {')': '(', ']': '[', '}': '{'}[ch]
            for k in range(len(stack) - 1, -1, -1):
                if stack[k][0] == match:
                    stack = stack[:k]
                    break
        if ch == '\n':
            line += 1
    stack = [(b, p, l) for b, p, l in stack if pos - p < 128]
    tex = text.endswith('\\') or (tex and text.isalpha())
    return (doc, stack, line, tex), float(value)

"""A sparse spelling detector for short b-initial roots.

The largest negative responses are to bend/bent, bump, bang, bash, beam,
and related short b syllables. A root can be completed across a token boundary.
Whole-token compounds and long preceding words weaken or suppress this rule.
Positive values cover b + ad/od-like continuations. Chinese bend characters
and a few Japanese b-syllable loanwords have their own negative rules.
Cyrillic and split accented spellings are transliterated. UTF-8 fragments
are joined before inspecting characters; document boundaries reset state.
Most other tokens receive zero, not a general semantic or b-letter response.
"""
import regex as re
import codecs
from anyascii import anyascii
from functools import lru_cache

READS = ()

# Typical magnitudes at a space-leading spelling of the root.
STRENGTH = {
    'bend': 5.4,
    'bent': 5.6,
    'bump': 5.1,
    'bang': 4.4,
    'bash': 3.95,
    'beam': 3.85,
    'beat': 2.7,
    'byte': 2.6,
    'bite': 3.7,
    'bow': 3.6,
    'bam': 3.9,
    'beng': 3.4,
    'bom': 1.15,
    'bomb': 1.2,
    'boom': 1.15,
    'bounc': 2.1,
}
ROOT = re.compile(
    r'(bend|bent|bump|bang|bash|beam|beat|byte|bite|bow|bam|bat|'
    r'beng|bomb|boom|bom|bounc)(s|es|ed|en|ing|er|ers|y|e|ted|ting)?'
    r'(?=$|[^a-z])', re.I
)
STRENGTH['bat'] = 2.05


@lru_cache(maxsize=32768)
def response(previous, text):
    # The Chinese bend character is another strong, direct spelling trigger.
    if any(ch in text for ch in '弯彎'):
        return -6.5 if len(text.strip()) == 1 else -4.0
    if '掰' in text:
        return -2.2
    # Japanese loanword syllables containing /b/, including byte (バイト).
    joined_japanese = previous + text
    for spelling, magnitude in (('バイト', 6.5), ('バーム', 5.0),
                                ('ブーム', 2.3), ('ボタン', 4.2)):
        at = joined_japanese.rfind(spelling)
        if at >= 0 and at + len(spelling) > len(previous):
            return -magnitude
    if re.search(r'\p{Script=Han}', text):
        return 0.0
    # Transliterate alphabetic b-fragments, not unrelated Asian syllables.
    if re.search(r'\p{Script=Cyrillic}', previous + text):
        previous, text = anyascii(previous), anyascii(text)
    elif previous.lower().endswith('b') and not text.isascii():
        text = anyascii(text)
    previous_lower = previous.lower()
    current = text.lower()
    if previous_lower.endswith('b'):
        if re.fullmatch(r'i?od(?:e|es|s)?', current):
            return 3.1
        if re.fullmatch(r'ad(?:e|er|s)?', current):
            return 1.3 if current in ('ad', 'ads') else 2.7
    joined = previous.lower() + text.lower()
    edge = len(previous)
    for match in ROOT.finditer(joined):
        start = match.start()
        if match.end(1) <= edge:
            continue
        # A root embedded inside one larger token is a different spelling.
        if start > edge and joined[start - 1].isalpha():
            continue
        root, suffix = match[1], match[2] or ''
        if suffix in ('en', 'e') and not (
            root == 'beat' and suffix == 'en'
            or root == 'bounc' and suffix == 'e'
        ):
            continue
        magnitude = STRENGTH[root]
        if start < edge:
            remainder = joined[edge:match.end(1)]
            fragment = re.search(r'[a-zA-Z]+$', previous)
            fragment = fragment[0] if fragment else ''
            size = len(fragment)
            factor = 1.15 if size == 1 else 0.8 if size == 2 else 0.6
            if size > 4:
                factor = 0.1
            if size > 1 and fragment[0].isupper():
                factor *= 0.4
            magnitude *= factor if re.search('[aeiouy]', remainder) else 0.1
        elif not text.startswith(' '):
            magnitude *= 0.6 if root == 'byte' else 0.75
        if root == 'bash' and '/bash' in current:
            magnitude = 6.5
        if root == 'byte' and previous.strip()[-1:].isdigit():
            magnitude *= 1.6
        if root == 'byte' and text.lstrip().startswith('B'):
            magnitude *= 0.4
        if suffix:
            if root == 'bend':
                pass
            elif root == 'beat' and suffix == 'en':
                magnitude *= 1.4
            elif root == 'beam' and suffix == 's':
                magnitude *= 1.25
            elif suffix in ('s', 'es'):
                magnitude *= 0.95
            elif root == 'bat' and suffix.startswith('t'):
                magnitude *= 1.5
            elif root == 'bounc' and suffix in ('e', 'ing'):
                pass
            else:
                magnitude *= 0.45
        return -magnitude
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        previous, pending = '', b''
    else:
        _, previous, pending = carry
    data = pending + prefix.token_bytes[-1]
    text, consumed = codecs.utf_8_decode(data, 'ignore', False)
    value = response(previous, text)
    return (document, text[-12:], data[consumed:]), float(value)

"""Approximate a declaration/import signal, not a full source-code parser.

Predict large negatives for module-opening keywords in import sections,
smaller negatives for line-initial declarations, and zero for most prose.
A decaying import count and a bounded text tail distinguish source, quoted
source, indentation and file beginnings. Initial `Title:` labels are also
negative; main entry points and two document-markup words are positive.
All context resets between documents.
"""
import re

READS = ()

DECLARATIONS = {
    'const': -1.1,
    'let': -1.45,
    'var': -1.15,
    'public': -0.8,
    'private': -1.1,
    'protected': -1.05,
    'static': -0.45,
    'final': -1.0,
    'readonly': -2.7,
    'pub': -0.5,
    'int': -0.55,
}
LINE_PREFIX = re.compile(r'[\s\d+|>\-`]*\Z')
CODE_CONTEXT = re.compile(
    r'\b(?:import|python|def|try|except)\b|\bprint\s*\('
    r'|"""|\.py\b|code:\s*$', re.I
)


RELEVANT = set(DECLARATIONS) | {
    'from', 'using', 'namespace', 'package', 'use', 'mod', 'import',
    'main', 'include', '$', 'document', 'uploaded', ':',
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, imports, age = '', 0.0, 0
    else:
        _, tail, imports, age = carry
    raw = prefix.token_strings[-1]
    word = raw.strip(' \t#')
    next_tail = (tail + raw)[-384:]
    if word not in RELEVANT:
        return (doc, next_tail, imports * 0.99, age + 1), 0.0
    text = tail.replace('\\n', '\n').replace('\\t', '\t')
    line = text.rsplit('\n', 1)[-1]
    start = bool(LINE_PREFIX.fullmatch(line))
    tab = raw.startswith('\t')
    bare = not raw.startswith((' ', '\t'))
    code = bool(CODE_CONTEXT.search(text))
    physical = tail.rfind('\n') > tail.rfind('\\n')
    p = 0.0

    if raw == ':' and age == 1 and tail == 'Title':
        p = -9.78
    elif word == 'from':
        if age == 0:
            p = -6.15 if bare else 0.29
            if raw.startswith('#'):
                p *= 0.52
        elif start:
            if tab:
                p = -4.4 - 3.7 * min(imports, 1.0)
            elif code or imports > 0.15:
                p = (-11.1 if physical else -7.0)
                p -= 2.5 * min(imports, 1.0)
                indent = re.sub(r'^\s*\d+\t', '', line)
                if not bare and len(indent.expandtabs()) > 6:
                    p *= 0.6
                if not bare and len(indent.expandtabs()) < 2:
                    p *= 0.35
                if not bare:
                    p *= 0.8
                if '`' in line:
                    p *= 0.4
            else:
                p = 0.25
        elif re.search(r'\bimport\b', line):
            p = -2.3
        elif bare and ('python -c' in line or 'file_text' in line):
            p = -2.1
    elif word in ('using', 'namespace') and bare and start:
        base, boost = (-2.65, 4.8) if word == 'using' else (-1.2, 5.3)
        p = base - boost * min(imports, 1.0)
        if '#include' in text:
            p = -2.0 if word == 'using' else -1.2
        elif word == 'namespace' and '<?php' in text:
            p = -6.7
    elif word == 'package' and bare and start:
        p = -3.82 if age == 0 else -1.7
        if '*/' in text:
            p = -4.8
    elif word in ('use', 'mod') and start:
        rust = bool(re.search(r'::|\.rs\b|#\[|\brust\b', text))
        if rust:
            p = -3.1 if tab or word == 'mod' else -1.8
        elif word == 'use':
            p = -0.6
    elif word == 'import':
        p = -0.15
        if start and age > 0:
            p = -1.5 if bare else -0.85
            if 'python' in text.lower() or 'from ' in text:
                p -= 0.8
    elif word in DECLARATIONS:
        if start or tab:
            p = DECLARATIONS[word]
            if word in ('public', 'private', 'protected') and bare:
                p *= 0.3
            if word == 'int' and bare and '#include' in text:
                p = 1.7
        elif word in ('final', 'static', 'readonly'):
            if re.search(r'\b(?:public|private|protected|static)\b', line):
                p = DECLARATIONS[word]
        elif word == 'const' and code:
            p = -0.6
    elif word == 'main':
        if re.search(r'\bint\s*`?\s*$', line):
            p = 3.6 if '#include' in text else 1.8
        elif re.search(r'\b(?:void|func|fn|package)\s*`?\s*$', line):
            p = 1.0
        elif line.endswith('__'):
            p = 1.7
        elif start and '__main__' in text:
            p = 2.5
    elif raw == '#include':
        p = -0.65
    elif word == '$' and start:
        p = -0.6
    elif word == 'document' and line.endswith('begin{'):
        p = 1.7
    elif word == 'uploaded' and line.endswith(('<', '</')):
        p = 1.2

    if word in ('import', 'from', 'using', 'use', 'package'):
        if (start or tab) and (word != 'from' or p < -1.0):
            imports = min(5.0, imports + 1.0)
    imports *= 0.99
    return (doc, next_tail, imports, age + 1), float(p)

"""Approximate two observed regimes: first-person plural and document startup.

Inside documents, predict negative values for we/us/our and multilingual
counterparts, weaker values for third-person pronouns, some Romance plural
verb endings, and a short tail after 'we'. A left-boundary check suppresses
matches to continuation fragments. Document starts instead use spacing,
case, length, script and grammatical classes. These coarse startup rules
leave much word-specific variation unexplained. Other positions predict zero.
"""
import math
import regex

READS = ()

FUNCTION_WORDS = set(
    'a an the this that these those of in on at to for from by with without '
    'into onto over under above below before after between among through '
    'during about against within upon out off per via as and but or nor so yet '
    'if because while when since although though unless until whether than then'
    .split()
)
SUBJECTS = set('wir nous nosotros nosotras noi nós wij vi мы'.split())
OBJECTS = set('uns oss ons нас нам'.split())
POSSESSIVES = set(
    'unser unsere unseren unserer unserem unseres notre nos '
    'nuestro nuestra nuestros nuestras nostro nostra nostri nostre '
    'nosso nossa nossos nossas onze vår vårt våra vores vore наш наша наши наше'
    .split()
)


def initial_value(s):
    w = s.strip()
    low = w.lower()
    space = s[:1].isspace()
    if s.startswith('<|'):
        return 9.041 if 'endoftext' in s else -0.515
    if not w:
        if '\n' in s or '\r' in s:
            return 1.447
        return min(3.8, 1.666 + 1.65 * math.log(max(1, len(s)))
                   + (1.0 if '\t' in s else 0.0))
    if w == 'I':
        return -4.896 if space else -9.568
    if low == 'we' and not w.isupper():
        return (-1.43 if w[0].isupper() else -4.298) if space else -6.224
    if low == 'you' and not w.isupper():
        return -3.049 if space else -5.202
    if low in {'he', 'she', 'they', 'us', 'our', 'my', 'your', 'his', 'her', 'their'}:
        return 0.89 if space else -1.92
    if low in {'hello', 'hi', 'hey', 'welcome'}:
        return -5.627
    if low == 'how':
        return -9.213 if w[0].isupper() else -1.26
    if low in {'what', 'why', 'where', 'who', 'which', 'whom', 'whose'}:
        return -1.249
    if low in FUNCTION_WORDS:
        return 1.305 if space else 1.152
    if space:
        return 0.255 if w[0].isupper() else 0.768
    if w.isdecimal():
        return -0.429
    if regex.search(r'\p{Script=Han}', w):
        return 0.529
    if w.isalpha():
        if len(w) == 1:
            return -3.873 if w.isupper() else -1.523
        if len(w) == 2:
            return -1.525 if w[0].isupper() else -1.203
        return -0.917 if w[0].isupper() else -0.537
    if w.startswith(('"', "'", '“', '”', '‘', '’', '`')):
        return -1.692
    if w.startswith(('/*', '//', '#!', '<?', '<!')):
        return -2.771
    return -1.4 if w.startswith('<') else 0.056


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    initial = carry is None or carry[0] != doc
    prev = '' if initial else carry[1]
    if initial:
        return (doc, s), initial_value(s)

    low = s.strip().strip('"“”‘’').lower()
    boundary = (s[:1].isspace() or s[:1] in '"“”‘’'
                or not prev or not prev[-1:].isalpha())
    value = 0.0
    if '我们' in s or '我們' in s:
        value = -0.65
    elif '咱们' in s or '咱們' in s:
        value = -0.28
    elif boundary and (not s.strip().isupper() or low == 'our'):
        if low == 'we':
            value = -0.80 if s[:1].isspace() else -0.53
            if s.strip()[:1].isupper() and s[:1].isspace():
                value = -0.66
        elif low == 'us':
            value = -1.22 if s.strip() == 'us' else -0.45
        elif low == 'our':
            value = -0.94
        elif low in {'ours', 'ourselves'}:
            value = -0.60
        elif low in SUBJECTS:
            value = -0.40 if low == 'vi' else (-0.81 if low == 'wij' else -1.5)
        elif low in OBJECTS:
            value = -1.45
        elif low in POSSESSIVES:
            value = -1.15
        elif low in {'he', 'she', 'her', 'they'}:
            value = {'he': -0.19, 'she': -0.30,
                     'her': -0.15, 'they': -0.08}[low]
            if s.strip()[:1].isupper():
                value *= 0.7
    # First-person plural endings in Romance-language verbs.
    elif low in {'iamo', 'amos', 'emos', 'imos'} and prev[-1:].isalpha():
        value = -0.60
    if prev.strip().lower() == 'we':
        if s in {"'ll", '’ll', "'re", '’re', "'ve", '’ve', "'d", '’d'}:
            value = -0.25
        elif low in {'have', 'will', 'should', 'can', 'are'}:
            value = -0.10
    return (doc, s), float(value)

programs.haiku:
"""Layer 1 MLP unit 645 (down_proj): a document-opening detector, plus a first-person-plural
detector for the rest of the text.

Plain-terms summary of what it does:
1. The first token of a document (the token right after <|endoftext|>, or the first token of a
   row). Here the model has no earlier context, so the unit reads only the word's identity:
   - an end-of-text marker opening a row -> strongly positive;
   - speech and question openers (I, We, You, He, How, Why, Hi, Hello, Welcome, Yes, ...),
     quote marks in front of them (“I, "We), and markup openers (<, <?, #!, ```) -> strongly negative;
   - a single capital letter, or another capitalised word with no leading space -> negative;
   - whitespace and indentation, and function words that continue a sentence (the, of, in, for,
     at, after, ...) -> positive;
   - other lower-case fragments -> slightly negative.
2. Everywhere else: first-person plural words (we, our, us, wir, nous, мы, ...) -> about -0.7.
   Other tokens are about zero.
"""

READS = ()

SPEECH_OPENERS = {
    "i", "we", "you", "he", "she", "they", "how", "why", "what", "where", "who",
    "hi", "hello", "hey", "welcome", "yes", "please", "ok", "oh", "wow", "thanks", "thank",
    "sorry", "dear", "good",
}
FIRST_PERSON_PLURAL = {
    "we", "our", "ours", "us", "ourselves", "wir", "uns", "unser", "nous", "nos", "notre",
    "мы", "нас", "nosotros", "我们",
}
FUNCTION_WORDS = {
    "the", "a", "an", "this", "that", "these", "those", "in", "on", "at", "for", "of", "to",
    "with", "from", "by", "after", "before", "if", "its", "your", "my", "their", "his", "her",
    "is", "are", "as", "or",
}
MARKUP = {"<", "<?", "#!/", "```", "**", "/*", "//", "--", "<!--"}
QUOTES = "\"“'("
END_OF_TEXT = "<|endoftext|>"


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    word = tok.strip().lower().lstrip(QUOTES)
    doc_start = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if not doc_start:
        return carry, -0.7 if word in FIRST_PERSON_PLURAL else 0.0
    if tok == END_OF_TEXT:
        return carry, 9.0
    if tok.strip() == "":
        return carry, 2.0
    if tok.strip() in MARKUP:
        return carry, -3.0
    if word in SPEECH_OPENERS:
        return carry, -6.0 if tok[:1] in QUOTES else -4.5
    if word in FUNCTION_WORDS:
        return carry, 1.3
    if len(tok.strip()) == 1 and tok.strip().isupper():
        return carry, -3.5
    if tok[:1].isupper():
        return carry, -0.9
    if tok[:1] == " ":
        return carry, 0.7
    return carry, -0.35

programs.sol:
"""Sparse local responses to tai-like spellings, rather than a topic.

Strong cases are Chinese 太/泰, Japanese タイ, Latin Tai/Thai and Korean
태. Adjacent token fragments can complete the same spellings. Tokenization
changes their strength, especially when a Korean syllable is byte-split.
Everything else is approximated by zero; this omits many smaller responses.
"""
import unicodedata

READS = ()


def activation(token, previous, tail, raw):
    word = token.strip()
    joined = (tail + raw).decode('utf-8', 'replace')
    if word.endswith('太') and word not in ('太太', '亚太'):
        return 6.5 if word in ('太', '不太') else 4.5
    if joined.endswith('泰'):
        return 7.0 if word == '泰' else 10.0
    if word in ('泰国', '泰國'):
        return 3.3
    if word == 'タイ':
        return 4.2
    if word == '태':
        return 1.3 if previous == '상' else 5.0
    if raw and raw[0] & 0xc0 == 0x80 and joined.endswith('태'):
        return 18.5 if (tail + raw).endswith(' 태'.encode()) else 9.0
    if (tail + raw).endswith('타'.encode()[:2]):
        return 2.0
    if word == 'тай':
        return 2.5
    latin = ''.join(c for c in unicodedata.normalize('NFD', word.lower())
                    if not unicodedata.combining(c))
    if latin == 'tai':
        return 4.6 if word.isascii() else 2.0
    if latin in ('thai', 'thailand'):
        return 3.1 if word.isascii() else 2.3
    if previous.endswith(('た', 'だ', 'あ')) and word == 'い':
        return 3.0
    if previous.endswith('タ') and word == 'イ':
        return 2.0
    if token != word:  # Do not join fragments across a space.
        return 0.0
    prev = previous.strip().lower()
    if prev.endswith(('t', 'th')) and word in ('ai', 'AI', "'ai"):
        if prev.endswith('th'):
            return 7.0
        return 0.7 if prev.endswith('st') else 4.0
    recent = tail.decode('utf-8', 'ignore').lower()
    if recent.endswith('tha') and latin.startswith('i'):
        return 4.5
    if prev.endswith('ta') and latin == 'i':
        return 3.5
    if prev.endswith('т') and word == 'ай':
        return 5.7 if prev == 'т' else 2.3
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous, tail = '', b''
    if carry is not None and carry[0] == document:
        previous, tail = carry[1:]
    token, raw = prefix.token_strings[-1], prefix.token_bytes[-1]
    value = activation(token, previous, tail, raw)
    return (document, token, (tail + raw)[-8:]), value

"""Approximate this component with local words, spellings and collocations.

Trust forms give the strongest negative responses. Stress/rust words and
" in" after belief, investment or difference expressions are also negative.
Smaller rules distinguish short s-t spelling fragments. Common English
words bypass the main s-t fragment rules. Transliteration extends
these spelling tests to other alphabets; a dictionary identifies Chinese
trust words. The only context retained is a short, normalized text tail.
"""
import re
import regex
from functools import lru_cache
from anyascii import anyascii
from wordfreq import zipf_frequency
import cedict

READS = ()

@lru_cache(16384)
def _latin(s):
    return anyascii(s).lower()

@lru_cache(16384)
def _uncommon(word):
    return zipf_frequency(word, 'en') < 4.1

@lru_cache(8192)
def _chinese_trust(s):
    if len(s) < 2 or not regex.fullmatch(r'\p{Script=Han}{2}', s[-2:]):
        return False
    return any(g.strip() == 'to trust' for g in cedict.glosses(s[-2:]))

def _predict(s, tail):
    a = _latin(s)
    frag = a.strip()
    m = re.search('[a-z]+$', tail)
    prev = m[0] if m else ''
    # Preposition collocations, classified by the preceding word.
    if a == ' in':
        if 'trust' in prev:
            return -4.7
        if prev in ('confident', 'confidence'):
            return -3.8
        if re.search('believ|belief|faith', prev):
            return -2.6
        if re.fullmatch(r'(?:re)?invest(?:s|ed|ing)?', prev):
            return -2.8
        if re.fullmatch(r'investments?|stake', prev):
            return -1.8
        if prev == 'interested':
            return -0.49
        if prev in ('interest', 'interests'):
            return -1.3
        if prev.startswith('differ'):
            return -0.63 if prev == 'different' else -1.9
        if prev in ('best', 'worst', 'latest', 'finest'):
            return -1.9
        if prev in ('lost', 'loss', 'losing', 'doubt', 'lying'):
            return -0.61
        if prev in ('trade', 'advances', 'progress', 'stake'):
            return -0.42
        return 0.022
    if _chinese_trust(s):
        return -3.4
    if not re.fullmatch('[a-z]+', frag):
        return -0.0027
    continued = a[0].isalpha()
    word = prev + frag if continued else frag
    # Lexical families are stronger than the generic spelling responses.
    if 'st' in frag:
        if re.search(r'trust(?:ed|ing|s)?$', word):
            if 'trust' not in frag:
                return -11.0
            if word.endswith('entrusted'):
                return -2.1
            if word.endswith(('trusted', 'trusting')):
                return -4.7
            return -6.4
        if re.search(r'(?:^|di)stress(?:ed|es|ful)?$', word):
            return -0.75 if word.endswith(('ful', 'ed')) else -1.8
        if word.endswith('thrust'):
            return -3.0
        if word.endswith('rust'):
            return -4.7 if frag == 'ust' else -2.0
        if frag == 'contrast':
            return -1.1 if prev != 'in' else -0.0027
        if frag == 'finest':
            return 0.19
        if frag in ('fest', 'fist'):
            return 2.3
        # For other s-t fragments, common whole English words are quiet.
        if continued and prev and len(frag) <= 5 and _uncommon(word):
            if re.search(r'[bf]st|sst', word):
                return 0.16
            if re.search(r'tr[aeiou]s', word):
                return -0.97
            if re.search(r'[rl][aeiouy]?st|st[rl]', word):
                return -0.25
            if re.search(r'[aeiouy]{2}st', word):
                return 0.087
            if 'est' in frag:
                return 0.085
            if 'ust' in frag:
                return 0.11
            if 'ist' in frag:
                return -0.038
            return 0.026
    if frag == 'confidence':
        return -0.66
    if (continued and prev and len(frag) <= 5 and
            re.search(r'tr[aeiou]s$', word) and 's' in frag):
        return -0.97
    if (continued and prev and len(frag) <= 5 and
            re.match(r'r[aeiou]ss?', frag) and prev.endswith('t')):
        return -0.97
    return -0.0027


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    value = _predict(token, tail)
    return (doc, (tail + _latin(token))[-80:]), value

programs.haiku:
"""The 'to' / 'into' / arrow that names the destination of a change or range.

Fires on the word that points from a starting state to a result: "from 5 to 1",
"convert X into Y", "changes to", "moved to", "range of 3 to 7", "A -> B".
Near zero on other uses of "to": infinitives ("need to", "want to"), "according to",
"due to", "required to", and so on. Chinese 到/至 count as "to" and 从 as "from".
"""

READS = ()

# Verbs and nouns of change, conversion, movement or transfer.
CHANGE_WORDS = {
    "convert", "converts", "converted", "converting", "conversion", "change", "changes",
    "changed", "changing", "transform", "transforms", "transformed", "transfer", "transfers",
    "transferred", "switch", "switched", "translate", "translated", "turn", "turns", "turned",
    "shift", "shifted", "reduce", "reduced", "reduces", "increase", "increased", "decrease",
    "decreased", "map", "mapped", "rename", "renamed", "replace", "replaced", "update", "updated",
    "round", "rounded", "scale", "scaled", "migrate", "migrated", "modify", "modified", "morph",
    "morphing", "split", "cut", "export", "exported", "promoted", "moved", "moving", "move",
    "adapted", "relocated", "upgraded", "transition", "transitioned",
}
# Words that make a following "to" an infinitive or a fixed phrase, not a destination.
INFINITIVE_WORDS = {
    "need", "needs", "needed", "want", "wants", "wanted", "how", "according", "due", "have",
    "has", "had", "able", "unable", "required", "require", "requires", "important", "possible",
    "easy", "likely", "trying", "try", "tried", "decided", "not", "used", "willing", "ready",
    "like", "prior", "compared", "related", "equal", "close", "similar", "access", "respect",
    "adjacent", "referred", "applied", "found", "add", "adds", "adding", "designed", "allowed",
    "happy", "continue", "continues", "seem", "seems", "appears", "known", "welcome", "contribute",
    "provide", "attempt", "reason", "enough", "good", "subject", "bring", "feel", "is", "was",
    "are", "be", "you", "order", "me", "us", "them", "him", "her",
}
NUMBER_END = {"%", "³", "”", ")"}
TO_WORDS = {" to": 0.15, "to": 0.15, " To": 0.15, "To": 0.15, "到": 0.6, "至": 0.6}
INTO_WORDS = {" into": 0.85, "into": 0.85, " Into": 0.85}
ARROWS = {" ->": 1.1, " →": 1.1, " -->": 1.1}
WINDOW = 15


def step(carry, prefix, upstream):
    t = prefix.position
    doc = prefix.document_ids
    token = prefix.token_strings[t]
    base = TO_WORDS.get(token, INTO_WORDS.get(token, ARROWS.get(token)))
    if base is None:
        return None, 0.0
    # The words in the same document before this token, most recent last.
    before = []
    for j in range(max(0, t - WINDOW), t):
        if doc[j] == doc[t]:
            before.append(prefix.token_strings[j].strip().lower())
    near = before[-6:]
    prev = before[-1] if before else ""
    value = base
    if "from" in near or "从" in near:
        value += 2.9  # "from X to Y": the start of a range or change
    elif "from" in before or "从" in before:
        value += 1.0
    if any(w in CHANGE_WORDS for w in before[-8:]):
        value += 1.5  # "convert ... to", "changed ... to", "moved to"
    if prev.replace(",", "").isdigit() or prev in NUMBER_END:
        value += 0.4  # "3 to 7", "50% to"
    if any(w.replace(",", "").isdigit() for w in before[-3:]):
        value += 0.5
    if prev in INFINITIVE_WORDS and "from" not in near:
        value = 0.0  # "need to", "according to": not a destination
    return None, max(value, 0.0)

programs.sol:
"""Local English quantity and noun-phrase constructions.

Positive: floating quantifiers ('are all', 'students each'), some indefinite
noun phrases, and pronominal copular complements. Negative: 'variety/range of',
possessive temporal modifiers, and words contrasting alternatives. Values are
rough amplitudes, not grammaticality judgments. Other lexical effects are
omitted. Rules match lower-case, space-prefixed word tokens. Only three
preceding tokens are kept; documents reset this history.
"""
from functools import lru_cache
import wordnet

READS = ()
BE = set("is are was were am be been being 's ’s 'm ’m 're ’re".split())
AUX = set("can could may might must will would should have has had 've ’ve".split())
PREP = set("of to for in on at from with by as into over under among between".split())
POSS = set("my your his her its our their whose".split())
ADVERBS = set("also not always already still apparently even just".split())
TEMPORAL = set("first last next early late past previous prior final".split())
BREADTH = set("wide wider broad broader diverse full whole complete".split())
# Columns: ordinary use, after 'be', after an auxiliary.
QUANTIFIERS = {
    'all': (0.4, 3.8, 2.0), 'each': (0.4, 2.0, 3.6),
    'both': (0.3, 1.0, 0.3), 'either': (0.4, 1.5, 1.4),
    'neither': (0.3, 0.6, 0.5), 'such': (0.9, 3.5, 0.3),
}
INDEFINITE_NOUNS = {
    'number': 1.0, 'part': 2.6, 'result': 1.3, 'chance': 2.5,
    'opportunity': 1.6, 'function': 0.8, 'half': 1.0,
    'matter': 0.7, 'example': 0.5, 'problem': 0.5,
    'majority': 2.3, 'plurality': 1.0,
}


@lru_cache(maxsize=4096)
def noun_subject(word, before):
    pos = wordnet.parts_of_speech(word)
    markers = {'the', 'these', 'those', 'two', 'three', 'many', 'several', 'and'}
    context = 'verb' not in pos or before in markers or before.isdigit()
    plural = any(b != word and 'noun' in wordnet.parts_of_speech(b)
                 for b in wordnet.base_forms(word))
    return 'noun' in pos and context, 'noun' in pos and plural and context


def predict(w, p, pp, earlier):
    frame = pp if p in ADVERBS and pp in BE | AUX else p
    if w in QUANTIFIERS:
        ordinary, copular, auxiliary = QUANTIFIERS[w]
        if frame in BE:
            v = copular
            if frame == 'are':
                v = {'all': 3.0, 'each': 4.6, 'both': 2.0}.get(w, v)
            if w == 'all' and frame == 'is':
                v = 4.4
            if w == 'either' and frame == 'be':
                v = 0.9
            if w == 'such' and pp == 'there':
                v = 0.2
            return v
        if frame in AUX:
            if w == 'both' and frame not in {'have', 'has', 'had'}:
                return 2.0
            return auxiliary
        if p in PREP | {'and', 'or', 'but', 'if', 'that'}:
            return {('each', 'with'): 0.7, ('both', 'as'): 0.6,
                    ('such', 'as'): 1.6}.get((w, p), 0.05)
        if not p or p in {',', '.', ';', ':'}:
            return 0.15
        if w == 'all' and p in {'you', 'we', 'they', 'this', 'a', 'an', 'the'}:
            return 1.1 if p == 'we' else 2.7
        noun, plural = noun_subject(p, pp)
        if w == 'each':
            if plural or p.isdigit() or p in {'who', 'which'}:
                return 3.0
            return 1.3 if noun else 0.3
        if w in {'all', 'both'} and (plural or p.isdigit() or p in {'who', 'which'}):
            return 2.2 if w == 'all' else 1.5
        return ordinary

    if w == 'of':
        if p == 'variety':
            if pp in BREADTH:
                return -5.5
            return -1.0 if pp == 'the' else -2.7 if pp in POSS else -4.2
        if p in {'range', 'array', 'spectrum', 'gamut', 'assortment'}:
            if pp in BREADTH:
                return -6.0 if p == 'range' and pp in {'wide', 'wider'} else -4.7
            return -2.8 if p == 'range' and pp in {'a', 'an'} else -0.6
        if p in {'myriad', 'multitude', 'plethora'}:
            return -3.2
        if p in {'wealth', 'host'}:
            return -1.5
        if p in {'plurality', 'proportion', 'fraction', 'percentage', 'types'}:
            return -1.0
        if p in {'amount', 'portion', 'percent', 'series'}:
            return -0.4
        if p == 'one':
            after_be = pp in BE or (pp == 'not' and earlier in BE)
            return 1.45 if after_be else 0.15
        return -0.1 if p == 'number' else 0.3 if p in {'each', 'example'} else 0.0

    if w in TEMPORAL | {'only'}:
        if p in POSS:
            return -3.2 if w in {'last', 'past', 'only'} else -1.9
        if p in {"'s", '’s'}:
            return -2.5 if w in {'last', 'past'} else -0.4
        if p in {'a', 'an'}:
            return -1.7 if w in {'past', 'previous', 'early'} else -0.7
        if w == 'only':
            return -0.75 if p == 'the' else -0.35 if p in BE else 0.05
        if w == 'past' and p in BE:
            return -2.4
        return -0.3 if w in {'early', 'past'} else 0.12 if p == 'the' else 0.03
    if w in {'what', 'there', 'something', 'itself', 'themselves'}:
        if frame in BE:
            return 1.5 if w == 'something' else 3.0 if p in ADVERBS else 2.1
        return -0.1 if w in {'what', 'there'} else 0.0
    if w in INDEFINITE_NOUNS:
        if p in {'a', 'an'}:
            return INDEFINITE_NOUNS[w]
        if w == 'number' and p in {'large', 'greater', 'good', 'small', 'any'}:
            return 1.4
        return 0.55 if w == 'part' and p in BE else 0.0
    if w in {'different', 'wide', 'unique'}:
        return -1.0 if p in {'a', 'an'} else -0.5 if p in BE | AUX else -0.1
    if w in {'other', 'others', 'various', 'respective', 'variety',
             'differences', 'former', 'latter'}:
        if w == 'other':
            return 0.1 if p == 'each' else -1.7 if p in BE | POSS else -0.15
        return -0.45
    if w == 'difference':
        return -2.1 if p in {'a', 'an'} else -0.05 if p == 'the' else -0.7
    if w in {'many', 'several', 'any', 'none'} and p in BE | {'have', 'has'}:
        return -2.5 if w == 'none' else -1.2
    return 0.0


def step(carry, prefix, upstream):
    s, doc = prefix.token_strings[-1], prefix.document_ids[-1]
    history = () if carry is None or carry[0] != doc else carry[1]
    raw = history[-1] if history else ''
    p = raw.lower()
    pp = history[-2].lower() if len(history) > 1 else ''
    earlier = history[-3].lower() if len(history) > 2 else ''
    if p in {'s', 'm', 're', 've'} and pp in {"'", '’'}:
        p = "'" + p
    if raw[:1].isupper() and p in BE:
        p = '?'  # Question-initial 'Is/Are', not a predicate frame.
    w = s.strip().lower()
    value = predict(w, p, pp, earlier) if s == ' ' + w and w.isalpha() else 0.0
    return (doc, (history + (s.strip(),))[-3:]), float(value)

programs.haiku:
"""Component layers.1.mlp.down_proj:649 (layer 1 MLP, down projection), read from the words.

The component is silent on almost every token. Its activation is large on a few word
patterns, and the sign depends on the pattern:

* "of" after a word for a broad variety or range ("a variety of", "a wide range of",
  "a myriad of", "a multitude of"): strongly negative, -2.5 to -4. Weaker negative after
  "an array of", "a spectrum of", "a plurality of". "Types of" and "number of" are faintly
  negative; "kind of", "lot of" and "one of" are near 0 or slightly positive.
* The quantifiers "all", "each", "such", "both", "either" that follow a form of "be"
  ("is all", "are each", "are such that"): strongly positive, about +3. After a modal or
  auxiliary ("can all", "have each") about +1.7, after a pronoun ("we all", "they both")
  about +1.2. Elsewhere, after a noun or a comma, about +0.5.
* "be" followed by "what", "something", "there", "itself", "forward", "thus": about +1.5.
* "a number of", "a part of", "a chance to", "a result of": about +1.
* "therefore" and "thus": about +0.7.
* "be" or an auxiliary followed by "any", "many" or "none" ("are many", "have any"): about -1.
* A possessive followed by an order word ("his last", "my first", "our previous", "your
  only") or "a different" / "a difference": about -1.5.
* A few words are negative whatever comes before: "sorry" (-2.5), "already", "alone",
  "beyond" (about -1).

Everything else predicts 0. The program reads only the previous token and the current token
(in the same document), so it carries no state.
"""

READS = ()

VARIETY_NOUNS = {" variety", " range", " myriad", " multitude"}
SPREAD_NOUNS = {" array", " spectrum", " plurality", " assortment", " breadth", " plethora"}
PARTITIVE_NOUNS = {" types", " portion", " proportion", " fraction", " percentage", " percent",
                   " amount", " series", " number"}
QUANTIFIERS = {" all", " each", " such", " both", " either"}
BE_FORMS = {" is", " are", " was", " were", " be", " been", " being", " am", "'s", "’s", "'re", "’re", "'m", "’m"}
AUXILIARIES = {" must", " should", " would", " could", " can", " will", " may", " might", " shall",
               " has", " have", " had", " do", " does", " did"}
PRONOUNS = {" we", " they", " you", " them", " it", " I", " he", " she", " us"}
PREPOSITIONS = {" for", " in", " of", " from", " to", " at", " by", " on", " and", " or", " with", " about", ","}
POSSESSIVES = {" his", " her", " my", " your", " our", " their"}
A_PARTITIVE = {" part", " chance", " result", " number", " majority", " multiple", " half", " opportunity"}
BE_COMPLEMENTS = {" what", " something", " there", " forward", " itself", " thus", " therefore"}
NONE_OF_THESE = {" any", " many", " none"}
ORDER_WORDS = {" last", " past", " first", " previous", " next", " only"}
NEGATIVE_ANYWHERE = {" sorry": -2.5, " already": -1.0, " alone": -1.0, " beyond": -1.0}


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    same_doc = len(prefix.token_strings) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2] if same_doc else ""
    value = 0.0
    if cur == " of":
        if prev in VARIETY_NOUNS:
            value = -3.0
        elif prev in SPREAD_NOUNS:
            value = -1.2
        elif prev in PARTITIVE_NOUNS:
            value = -0.3
        elif prev == " one":
            value = 0.6
    elif cur in QUANTIFIERS:
        if prev in BE_FORMS:
            value = 2.8
        elif prev in AUXILIARIES:
            value = 1.7
        elif prev in PRONOUNS:
            value = 1.2
        elif prev not in PREPOSITIONS:
            value = 0.5
    elif cur in NONE_OF_THESE and (prev in BE_FORMS or prev in AUXILIARIES):
        value = -1.0
    elif cur in BE_COMPLEMENTS and prev in BE_FORMS:
        value = 1.5
    elif cur in {" therefore", " thus"}:
        value = 0.7
    elif cur in A_PARTITIVE and prev == " a":
        value = 1.0
    elif cur in ORDER_WORDS and prev in POSSESSIVES:
        value = -1.5
    elif cur in {" different", " difference"} and prev == " a":
        value = -1.5
    elif cur in NEGATIVE_ANYWHERE:
        value = NEGATIVE_ANYWHERE[cur]
    return carry, value

programs.sol:
"""Detect English partitives and the selection of alternatives.

The strongest responses are on 'of' after any/each/which/either, and on
'from' or 'between' after choosing. Some response carries into the article
in 'each of the'. Selective/selectivity words also respond. Distributive
phrases like 'every other' have the opposite sign. Everything else is near
zero. Generic 'One of ...' descriptions are weaker than explicitly choosing
a member. The buffer is limited to 160 characters and resets per document;
this is a local phrase recognizer, not a model of arbitrary syntax.
"""
import re
from functools import lru_cache
import wordnet

READS = ()

# Strength on 'of', then on the article in '... of the'.
PARTITIVE = {
    'any': (8.2, 3.0),
    'each': (6.4, 3.5),
    'which': (6.8, 0.8),
    'either': (6.8, 0.5),
    'one': (1.5, 0.35),
    'none': (1.6, 0.55),
    'neither': (1.8, 0.5),
    'all': (0.3, 1.1),
    'both': (0.2, 0.2),
}
CHOOSING = {'choose', 'select', 'pick'}
CONTRAST = {'distinguish', 'discriminate', 'differentiate',
            'balance', 'split', 'convert'}
SEQUENTIAL = set('subsequent consecutive particular following next second'.split())
SELECT_WORD = re.compile(r'\b(selective|selectively|selectivity|selectivities|'
                         r'selector|selectors|elective)$')
WORD_STRENGTH = {
    'selective': 3.5,
    'selectively': 5.5,
    'selectivity': 8.7,
    'selector': 2.0,
    'elective': 2.5,
}


ROOTS = CHOOSING | CONTRAST | set(WORD_STRENGTH) | {
    'decide', 'choice', 'combination', 'mixture', 'subset', 'be', 'become',
}


@lru_cache(maxsize=4096)
def base(word):
    # WordNet supplies inflections, including irregular forms like 'chosen'.
    return next((w for w in wordnet.base_forms(word) if w in ROOTS), word)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    s = token.strip().lower()
    full = (text + token).lower()
    words = re.findall(r'[a-z]+', text.lower())
    # Punctuation interrupts attachment: SELECT * FROM is not 'select from'.
    adjacent = bool(re.search(r'[a-zA-Z]\s*$', text))
    prev = words[-1] if words and adjacent else ''
    pp = words[-2] if len(words) > 1 else ''
    root = base(prev)
    separated = token[:1].isspace() or text[-1:].isspace() or not text
    value = 0.0
    if s == 'of' and separated:
        value = PARTITIVE.get(prev, (0.0, 0.0))[0]
        if root in {'combination', 'mixture', 'subset'}:
            value = 1.1
        if prev == 'one':
            # Generic 'One of ...' versus choosing a particular member.
            if re.search(r'\bOne\s*$|[.,;!?]\s*one\s*$', text):
                value = 0.0
            elif base(pp) in {'be', 'become'}:
                value = 0.7
            elif pp in {'to', 'into', 'by', 'least'}:
                value = 4.3
            if pp in {'which', 'each', 'every', 'any', 'either'}:
                value = 6.0
            if base(pp) in CHOOSING:
                value = 9.0
        if prev == 'more':
            value = 1.3
    elif token == 'Of' and prev in {'any', 'all', 'one'}:
        value = 6.5  # Schema combinators: anyOf, allOf, oneOf.
    elif s == 'the' and separated and prev == 'of':
        value = PARTITIVE.get(pp, (0.0, 0.0))[1]
    elif s in {'from', 'between', 'among', 'amongst', 'to'}:
        value = 0.3 if s == 'between' else 0.0
        if separated or s == 'between':
            if root == 'choose':
                value = {'from': 6.5 if prev in {'chosen', 'chose'} else 11.0,
                         'between': 10.0, 'among': 5.0, 'amongst': 5.0,
                         'to': 0.0 if prev == 'chosen' else 1.9}[s]
            elif root in {'select', 'pick'} and not text.split()[-1].isupper():
                value = {'from': 6.0, 'between': 7.0, 'among': 4.0,
                         'amongst': 4.0, 'to': 0.5}[s]
            elif s == 'between':
                if prev in {'choice', 'decision'} or root == 'decide':
                    value = 8.0
                elif root in CONTRAST:
                    value = 2.8
                elif prev in {'random', 'fill'}:
                    value = 3.8
            elif s in {'among', 'amongst'} and prev == 'which':
                value = 6.5
    elif s == 'one' and separated:
        if root in CHOOSING:
            value = 3.0
        elif prev in {'which', 'each', 'any'}:
            value = 2.0
    elif s == 'or' and separated and prev in {'one', 'either', 'any'}:
        value = 0.8
    elif s == 'other' and prev in {'each', 'every'}:
        value = -0.8 if prev == 'each' else -4.1
    elif s in SEQUENTIAL and prev in {'each', 'every'}:
        value = -3.5
    elif s in {'more', 'additional'} and prev == 'one':
        value = -1.2
    elif s == '.choice' or base(s) == 'choice':
        value = 2.2 if s == '.choice' else 0.5
    match = SELECT_WORD.search(full)
    if match:
        value = WORD_STRENGTH[base(match[1])]
    return (doc, (text + token)[-160:]), float(value)

programs.haiku:
"""Choosing-from-a-set detector for layers.1.mlp.down_proj:651.

The component is silent almost everywhere. It switches on at the word that opens a
"pick one item out of a set" phrase, the place where the text is about to name the
options:
  - "of" after a quantifier: "any of", "each of", "which of", "either of" (strong),
    "one of" (strong after a choice cue or "which", weak in "X is one of the best"),
    "any or all of", "one or more of" (moderate);
  - "from" and "between" after a choosing word: "choose from", "selected from",
    "replacement from", "choose between", "distinguish between" (strong);
  - the "the" right after "any of" / "each of" (weak);
  - the "one" in "select one", "pick one" (moderate);
  - the "ivity" / "selective" that follows "select" (selectivity, selective).
It goes negative on "other", "subsequent", "consecutive", ... after "every" ("every other").
Everything else predicts 0. Predictions are in the component's own activation units.
"""

READS = ()

QUANTIFIERS = {"any", "each", "which", "either", "whichever", "neither", "every"}
CHOICE_WORDS = {
    "choose", "chose", "chosen", "choosing", "choice", "choices", "select", "selected",
    "selects", "selecting", "pick", "picked", "random", "randomly", "distinguish", "options",
    "deciding", "decide",
}
# words that, after "every", mark a repeated-interval phrase ("every other", "every second")
REPEAT_WORDS = {"other", "subsequent", "consecutive", "particular", "second", "end", "passing"}
COPULAS = {"is", "was", "are", "were", "be", "been", "being", ",", ".", "and", "or"}


def _word(s):
    return s.strip().lower()


def step(carry, prefix, upstream):
    t = prefix.position
    words = [_word(s) for s in prefix.token_strings[max(0, t - 6) : t + 1]]
    cur = words[-1]
    prev = words[-2] if len(words) > 1 else ""
    prev2 = words[-3] if len(words) > 2 else ""
    recent = words[:-1][-4:]  # the four words before this one
    choice_cue = any(w in CHOICE_WORDS for w in recent)

    if cur in {"selectively", "selective", "selectivity"}:
        return None, 5.0
    if cur in {"ivity", "ive", "ively", "ivities"} and "select" in prev:
        return None, 8.0

    if cur == "of":
        if prev in QUANTIFIERS:
            return None, 7.0
        if prev == "one":
            if prev2 in COPULAS:
                return None, 0.5
            return None, 5.0 if (choice_cue or prev2 in QUANTIFIERS) else 2.0
        if prev in {"all", "more"} and any(w in QUANTIFIERS | {"one"} for w in words[-5:-2]):
            return None, 5.0
        if prev in {"none", "combination", "mixture", "subset"}:
            return None, 1.5
        return None, 0.0

    if cur == "the" and prev == "of" and prev2 in QUANTIFIERS:
        return None, 3.5
    if cur == "one" and prev in CHOICE_WORDS:
        return None, 4.0
    if cur == "from" and choice_cue and "*" not in words:
        return None, 8.0
    if cur == "between" and choice_cue:
        return None, 8.0
    if prev == "every" and cur in REPEAT_WORDS:
        return None, -4.0
    return None, 0.0

programs.sol:
"""Approximate a multilingual heart/mind-versus-center word-form signal.

English heart/mind and Chinese 心-family tokens are negative; center/centre
and standalone 中心 are positive. Hub modifiers boost centers, while
function words weaken them. Additional negative spellings/syllables include
Xin, tâm, 심/마음, 芯 and 음. Longer 心 compounds are weaker; worry is excluded.
The carry joins word pieces and UTF-8 bytes within each document. These are
lexical rules, not a general semantic classifier.
"""
import codecs
import re

READS = ()
FUNCTION_WORDS = {
    'the', 'a', 'an', 'of', 'and', 'to', 'at', 'in', 'on', 'for',
    'his', 'her', 'my', 'your', 'their', 'its', 'our', 'this', 'that',
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, b'', '')
    _, pending, before = carry
    raw = pending + prefix.token_bytes[-1]
    text, used = codecs.utf_8_decode(raw, 'ignore', False)
    state = (doc, raw[used:], (before + text)[-48:])
    piece = text.strip()
    low = piece.lower()
    previous = re.search(r'([A-Za-z]+)\Z', before)
    previous = previous[1] if previous else ''
    continuing = bool(text) and not text[0].isspace()
    joined = (previous + piece).lower() if continuing else low

    if low.strip('-') in {'center', 'centre', 'centers', 'centres'}:
        british = 'centre' in low
        value = 1.1
        if previous.lower() in {'data', 'business', 'trade'}:
            value = 5.5
        elif previous.lower() in FUNCTION_WORDS:
            value = 0.45
        elif piece[:1].isupper():
            value = 1.2 if british else (2.2 if previous.istitle() else 1.3)
        return state, value
    if low.strip('-') in {'centered', 'centred'}:
        return state, 0.25
    if low.strip('-') in {'mind', 'minds', 'minded'}:
        value = -3.6 if 'minded' in low else -2.5
        if before.lower().endswith('open') and 'minded' in low:
            value = -5.5
        return state, value
    if (continuing and low in {'ind', 'inds', 'inded'}
            and previous.lower().endswith('m')):
        return state, -7.0 if piece.isupper() else -4.1
    if low in {'heart', 'hearts'}:
        return state, -0.35 if piece[:1].isupper() else -1.1
    if joined == 'xin':
        if low == 'in':
            return state, -4.8
        return state, -2.8 if piece[:1].isupper() else -0.25
    if joined == 'tâm' or low == 'tâm':
        return state, -5.0
    if piece == '심':
        return state, -10.0 if pending else -5.5
    if piece == '음':
        return state, -3.5 if pending else -1.5
    if piece == '마음':
        return state, -4.2
    if piece == '芯':
        return state, -4.7
    if piece == '心':
        return state, -7.5 if pending else -5.0
    if '心' in piece:
        # Worry is a lexicalized exception, not a literal heart/mind form.
        if '担心' in piece or '擔心' in piece:
            return state, 0.0
        piece = piece.lstrip('的')
        if piece == '中心':
            return state, 1.1
        if '中心' in piece or '核心' in piece:
            return state, -0.6
        if piece.endswith('心'):
            if piece in {'心', '之心'}:
                return state, -5.0
            return state, -3.7 / max(1, len(piece) - 1)
        return state, -0.6
    return state, 0.0

"""Approximate a negative response to short i/ee-like spelling fragments.

An attached ending in a capitalized word is strongest; ordinary lowercase
words need a smaller value, especially outside English-looking prose.
Transliteration extends the ending test to Cyrillic, Arabic and katakana.
These are spelling/context rules, not a reconstruction of the MLP. Small
background responses and other scripts are left at zero.
"""
from functools import lru_cache
import math
import unicodedata
import regex
from anyascii import anyascii
from wordfreq import zipf_frequency, get_frequency_dict

READS = ()
ENGLISH_FUNCTION_WORDS = frozenset(
    'the of to and in is that was for with as by on from it be are this '
    'at an not have has which their a he she they his her its'.split()
)

@lru_cache(maxsize=32768)
def english_frequency(word):
    return zipf_frequency(word.lower(), 'en')

@lru_cache(maxsize=32768)
def written_frequency(word, language):
    frequency = get_frequency_dict(language).get(word.lower(), 0.0)
    return max(0.0, 9 + math.log10(frequency)) if frequency else 0.0

@lru_cache(maxsize=32768)
def spelling(token):
    word = token.strip()
    if not word or not all(unicodedata.category(c)[0] in 'LM' for c in word):
        return '', '', ''
    for script in ('Latin', 'Arabic', 'Cyrillic', 'Katakana'):
        if regex.search(r'\p{Script=' + script + '}', word):
            return script, word, anyascii(word).lower()
    return '', '', ''


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        word, english = '', 0.12
    else:
        _, word, english = carry
    token = prefix.token_strings[-1]
    attached = bool(word and token[:1].isalpha())
    english = .98 * english + .02 * (
        token.strip().lower() in ENGLISH_FUNCTION_WORDS
    )
    tail = regex.search(r'[^\W\d_]+$', token)
    if tail:
        word = ((word if tail.start() == 0 else '') + tail.group())[-64:]
    else:
        word = ''
    carry = document, word, english
    script, body, roman = spelling(token)
    spaced = token[:1].isspace()
    value = 0.0

    if script == 'Latin' and roman.endswith('i'):
        liquid = roman[-2:-1] in ('l', 'r')
        nasal = roman[-2:-1] in ('m', 'n')
        if spaced:
            if liquid or len(roman) == 1:
                value = -.22 if sum(c in 'aeiouy' for c in roman) > 1 else -.04
            else:
                value = .09 if len(roman) <= 3 else -.08
        elif len(word) <= 3:
            # Initials, short words and variables are not long name endings.
            if nasal or len(roman) == 1:
                value = -.05 if len(word) <= 2 else -.22
            else:
                value = -.12 if attached else .14
        elif word[:1].isupper():
            value = -.42 if body[:1].isupper() else -1.08
        else:
            value = -.60 if english > .094 else -.19

    elif script == 'Latin' and not spaced and roman.endswith('is'):
        frequency = english_frequency(word)
        if frequency <= 2.76:
            value = -.35 if len(roman) <= 2 else -.17
        elif frequency <= 6.51:
            value = -.10

    elif script == 'Latin' and not spaced and roman.endswith('ee'):
        if len(roman) <= 3:
            value = -.22 if len(word) > 4 else -.08

    elif script == 'Arabic' and body.endswith(('ي', 'ى', 'ی', 'ية')):
        if spaced:
            value = -.02 if body.endswith(('ية', 'ى')) else -.21
        else:
            value = -.84 if written_frequency(body, 'ar') > 1.96 else -.21

    elif script == 'Cyrillic' and roman.endswith('i'):
        if len(roman) <= 1:
            value = -.59 if english_frequency(body) <= 1.63 else -.09
        else:
            value = .13 if len(word) <= 3 else -.09

    elif script == 'Katakana' and roman.endswith('i'):
        if len(body) == 1:
            value = -.22 if len(roman) == 1 or roman[-2:-1] in ('l', 'r') else -.52
        else:
            value = -.30 if written_frequency(body, 'ja') <= 3.34 else -.07
    return carry, value

"""Sparse local-text approximation of this component.

Recognize scientific field-name compounds and several technical phrases.
For I (also informal i/im), use adjacent grammatical words and English
content words to distinguish embedded uses from punctuation-led ones.
Document beginnings and runs of interpuncts have separate offsets.
These are recurring training patterns, not a complete semantic parser;
unrecognized cases return zero.
"""
from functools import lru_cache
import re
import wordnet

READS = ()
SCIENCES = ('physics', 'chemistry', 'biology', 'mathematics',
            'engineering', 'medicine', 'technology')
AUXILIARIES = set(('do does did can could will would shall should '
                   'may might must').split())
SUBORDINATORS = set(('if when while that which what whether because '
                     'although since as').split())
CONNECTIVES = set(('and but or so yet now well thus hence however '
                    'therefore alternatively').split())
HEDGES = {'maybe', 'perhaps'}
DETERMINERS = set('a an the my your his her its our their this these those'.split())
PREPOSITIONS = set('of in on at to from for by with into through than'.split())
CODE_TYPES = set('int float double char long short bool var let string'.split())
FUNCTION_WORDS = (AUXILIARIES | SUBORDINATORS | CONNECTIVES | HEDGES |
                  DETERMINERS | PREPOSITIONS |
                  set(('is are was were be been being have has had '
                       'i you he she it we they not').split()))


@lru_cache(maxsize=16384)
def field_name(word):
    # Discipline-name morphology rules out polysemous abbreviations like IT.
    if not (word.endswith(('ology', 'istry', 'ics', 'metry', 'engineering'))
            or word in ('algebra', 'math', 'medicine')):
        return False
    return (wordnet.is_a(word, 'discipline') and
            any(wordnet.is_a(word, root) for root in SCIENCES))


@lru_cache(maxsize=16384)
def modifier(word):
    if not word or not word.isascii() or not word.isalpha() or word in FUNCTION_WORDS:
        return False
    pos = wordnet.parts_of_speech(word)
    return 'adjective' in pos or ('noun' in pos and 'verb' not in pos)


@lru_cache(maxsize=16384)
def content_word(word):
    return (len(word) > 2 and word not in CODE_TYPES and
            word not in FUNCTION_WORDS and
            bool(wordnet.parts_of_speech(word) & {'noun', 'verb'}))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous, prior_word = ('', '') if first else carry[1:]
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    prev = prior_word.lower()
    value = 0.0
    if first:
        if word.isascii() and word.isdigit():
            value = 0.49
        elif token.isspace():
            value = 0.40 if '\n' in token else 0.24
        elif word.isascii() and word.isalpha() and len(word) == 1:
            value = 0.35
        elif token.startswith('<|'):
            value = -0.15
        else:
            value = 0.08
    elif token and set(token) == {'·'} and previous and set(previous) == {'·'}:
        value = 0.63
    elif word == 'territorial' and prev == 'administrative':
        value = 1.33
    elif word in ('language', 'languages') and prev == 'programming':
        value = -0.68
    elif word == 'research' and prev in ('scientific', 'medical'):
        value = -0.53
    elif word == 'steel' and prev in ('structural', 'building'):
        value = 1.60
    elif word == 'assisted' and prev == 'computer':
        value = 0.85
    elif word == 'football' and prev == 'professional':
        value = 0.49
    elif token in ('I', 'i') and previous[-1:].isalpha():
        value = 0.0
    elif token in (' I', ' i', ' Im', ' im', 'I', 'i'):
        if prev in HEDGES:
            value = 0.48
        elif prev in AUXILIARIES:
            value = 0.41
        elif prev in SUBORDINATORS or prev in CONNECTIVES:
            value = 0.18
        elif prev in DETERMINERS:
            value = -0.27
        elif prev in PREPOSITIONS:
            value = -0.15
        elif previous.strip().endswith(','):
            value = 0.09
        elif previous.strip().endswith('.'):
            value = -0.08
        elif prev.isalpha():
            value = 0.25 if content_word(prev) else 0.03
        else:
            value = -0.05
    elif word == 'import' and ';' in previous and '\n' in previous:
        value = 0.18
    elif word.isascii() and word.isalpha() and modifier(prev) and field_name(word):
        if word.endswith('engineering'):
            value = 1.45
        else:
            value = 0.65 if token.strip()[:1].isupper() else 0.30

    # Keep the trailing word, joining alphabetic subword pieces when necessary.
    tail = re.search(r'[A-Za-z]+$', token)
