        tail_word = prior_word + token
    return (doc, token, tail_word[-64:]), value

programs.haiku:
"""Layer-1 MLP down-projection component 654, as a short rule-based predictor.

The component is quiet almost everywhere: its activation is near 0 on most tokens,
with a few word-level spikes and a small response at the start of each document.
The rules, strongest first:

- " territorial" right after " administrative" (the phrase "administrative
  territorial entity" in place-name facts): about +1.3.
- a Roman-numeral " I" right after a course or division name ("Algebra I",
  "NCAA Division I"): about +2.
- academic field nouns (Engineering, Mathematics, Physics, Algebra, ...): about +0.3.
- the pronoun " I" after a hedge or modal ("maybe I", "can I"): about +0.4;
  any other standalone " I" mid-sentence: about +0.1.
- the first token of a document: a digit about +0.5, a chat marker such as
  "<|im_start|>" about -0.15, anything else about +0.1.
Every other token predicts 0. The values are the group means measured on
training text, so the rules capture only the part of the variance that these
word classes explain; most of the activation is small, token-specific noise
that a short program does not capture.
"""

READS = ()

FIELD_NOUNS = {
    " Engineering", " engineering", " Mechanics", " Mathematics", " Biology",
    " Algebra", " Medicine", " Physics", " Chemistry", " Technology", " Science",
}
COURSE_NAMES = {" Division", " Algebra", " Analysis", " Math", " Calculus", " Geometry", " Physics"}
HEDGES = {" maybe", " Maybe", " perhaps", " Perhaps", " can", " Can", " do", " think", " sure", " Now"}


def step(carry, prefix, upstream):
    t = prefix.position
    tok = prefix.token_strings[t]
    prev = prefix.token_strings[t - 1] if t > 0 else ""
    new_doc = t == 0 or prefix.document_ids[t] != prefix.document_ids[t - 1]
    if new_doc:
        if tok.strip()[:1].isdigit():
            return carry, 0.5
        if tok.startswith("<|"):
            return carry, -0.15
        return carry, 0.1
    if tok == " territorial" and prev == " administrative":
        value = 1.3
    elif tok == " I" and prev in COURSE_NAMES:
        value = 2.0
    elif tok in FIELD_NOUNS:
        value = 0.3
    elif tok == " I" and prev in HEDGES:
        value = 0.4
    elif tok == " I":
        value = 0.1
    else:
        value = 0.0
    return carry, value

programs.sol:
"""A Q/QU spelling signal, with an echo into later pieces of the same word.

Short Q-bearing pieces are strongest; common complete words are weaker.
Another q in the same word is suppressed. Predictable French and TeX uses
are downweighted too. Related kw/kv spellings, Arabic qaf, and Unicode Q
forms get small parallel rules. This is not a general question detector.
Document starts and carriage-return runs have separate empirical offsets.
"""
import re
import unicodedata
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()


@lru_cache(maxsize=16000)
def q_piece(s):
    match = re.search(r'[A-Za-z]*[qQ][A-Za-z]*', s)
    if match is None:
        return None
    word = match.group()
    before = word.lower().index('q')
    space = s[:1].isspace()
    frequency = max(zipf_frequency(word.lower(), lang)
                    for lang in ('en', 'fr', 'es', 'pt', 'it', 'de'))
    n = len(word)
    if before == 0:
        if n == 1:
            return 2.9
        if n == 2:
            return 1.8 if space and not word[0].isupper() else 2.7
        if not space:
            return 1.9 if n <= 5 else 1.0
        return 0.7 if frequency >= 5.5 else 1.7 if n <= 6 else 0.9
    if before <= 2:
        return 0.3 if before == 1 and frequency >= 4.5 else 0.6
    return 0.1 if frequency >= 4.5 else 0.25 if frequency >= 3.5 else 0.6


def q_echo(distance, letters):
    if distance <= 1:
        if letters <= 2:
            return 3.0 if distance == 0 else 2.35
        return 2.05 if letters == 3 else 1.0
    if distance <= 3:
        return 1.14 if distance == 2 else 0.82
    if distance == 4:
        return 0.55
    return 0.24 if distance <= 7 else 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    _, prev, recent, raw = (doc, '', '', b'') if first else carry
    b = prefix.token_bytes[-1]
    s = prefix.token_strings[-1]
    # Complete a character split across byte-level tokens.
    if b and 128 <= b[0] < 192:
        s = (raw + b).decode('utf8', 'replace')
    rational_q = 'ℚ' in s
    s = unicodedata.normalize('NFKC', s)
    front = re.match(r'[^\W\d_]+', s)
    current = q_piece(s)
    value = current
    if current is not None:
        if s[:1].isalpha() and 'q' in prev.lower():
            if not (s[0].isupper() and prev[-1:].islower()):
                value -= 2.6
        # q completes a comparison macro, rather than naming the letter.
        if re.search(r'\\(?:ne|le|ge|sim|sime|e)$', recent):
            if s.startswith('q'):
                value = 0.15
        if recent.endswith(' ce') and s.lower().strip() == 'qu':
            value = 0.0
        # A variable in mathematical writing is weaker than an isolated Q.
        if value > 1 and s.strip().lower() == 'q':
            if len(re.findall(r'\b[A-Za-z]\b', recent)) >= 3:
                if ('=' in recent or '\\' in recent):
                    if not re.search('[_{};]', recent):
                        value = 1.7
    else:
        value = 0.0
        if front and 'q' in prev.lower():
            distance = len(prev) - prev.lower().rindex('q') - 1
            value = q_echo(distance, len(front.group()))
        elif 'ق' in s:
            value = 1.25 if len(s.strip()) <= 2 else 0.68
        elif front and 'ق' in prev:
            distance = len(prev) - prev.rindex('ق') - 1
            if distance <= 1:
                value = 1.8 if len(front.group()) <= 2 else 0.7
            elif distance <= 3:
                value = 0.4
        elif re.search(r'[kKкК][wvвВ]', s):
            value = 0.85 if len(s.strip()) <= 4 else 0.07
        elif prev.endswith(('k', 'K', 'к', 'К')):
            if s.startswith(('v', 'w', 'в', 'В')):
                value = 1.45
    if rational_q:
        value = 6.5
    if s == '\r':
        value = -3.7 if not recent.strip('\r') else -0.1
    if first:
        if current is not None:
            value = (2.3 if s.strip() == 'q' else
                     -0.24 if s.strip() == 'Q' else -0.8)
        else:
            value = (-3.7 if s == '\r' else
                     -4.3 if s == '\x00' else -0.33)
    tail = re.search(r'[^\W\d_]+$', s)
    word = tail.group() if tail else ''
    if front and len(front.group()) == len(s):
        word = prev + s
    # Retain only the last UTF-8 character's bytes for possible completion.
    raw = b[-4:]
    starts = [i for i, ch in enumerate(raw) if ch >= 192 or ch < 128]
    raw = raw[starts[-1]:] if starts else raw
    return (doc, word[-64:], (recent+s)[-100:], raw), value

programs.haiku:
"""Fires on the letter q inside spelling: a bare q-fragment ('q', 'Q', 'qu', 'QS', ' Q') is
strongest, most of all in the middle of a word; a whole word with 'qu' is weaker, and the
token right after a bare q-fragment is mildly active. Everything else is near zero."""
import re

READS = ()


def _letters(s):
    return re.sub(r"[^a-zA-Z]", "", s)


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    same_doc = len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    before = prefix.token_strings[-2] if same_doc else ""
    prev = _letters(before).lower()
    word = _letters(s).lower()
    if "q" in word and len(word) <= 2:
        mid_word = not s.startswith(" ") and before[-1:].isalpha()
        value = 2.5 if mid_word else 2.0
    elif "qu" in word:
        value = 1.0
    elif "q" in word:
        value = 0.3
    elif "q" in prev and len(prev) <= 2:
        value = 0.9
    else:
        value = 0.0
    return carry, value

programs.sol:
"""Predict from written syllable shapes and recognizable text markers.

Korean Hangul is split into first consonant, vowel and final consonant.
The largest bonuses are for n+(a, ae, ya) and r+a syllables.
Unfinished UTF-8 syllables retain their word boundary.

Other rules cover commas in Korean/Japanese, Vietnamese ra/ta/rồi, and
opening Title: fields and PHP tags. Other word-specific effects are omitted.
"""
import codecs
import unicodedata
from functools import lru_cache
import regex


READS = ()
INITIALS = 'ㄱㄲㄴㄷㄸㄹㅁㅂㅃㅅㅆㅇㅈㅉㅊㅋㅌㅍㅎ'
VOWELS = 'ㅏㅐㅑㅒㅓㅔㅕㅖㅗㅘㅙㅚㅛㅜㅝㅞㅟㅠㅡㅢㅣ'
N_LOW_SCORE = {'ㅏ': 4.2, 'ㅐ': 3.0, 'ㅑ': 2.4}
JAPANESE = regex.compile(r'[\p{Hiragana}\p{Katakana}]')
VIETNAMESE = regex.compile(r'[ăâđêôơưĂÂĐÊÔƠƯ\u1ea0-\u1ef9]')


@lru_cache(maxsize=50000)
def decode_token(raw, pending, at_word_start):
    decoder = codecs.getincrementaldecoder('utf8')('ignore')
    text = decoder.decode(pending + raw)
    tail = decoder.getstate()[0]
    space = at_word_start if pending else raw[:1].isspace()
    codes = [ord(c) - 0xac00 for c in text
             if unicodedata.name(c, '').startswith('HANGUL SYLLABLE ')]
    lead, unfinished = 0, False
    if tail and 0xea <= tail[0] <= 0xed:
        lo = (tail[0] & 15) << 12
        if len(tail) == 2:
            lo |= (tail[1] & 63) << 6
        hi = lo + (4095 if len(tail) == 1 else 63)
        lo, hi = max(lo, 0xac00), min(hi, 0xd7a3)
        if hi >= lo:
            unfinished = True
            if not codes:
                if len(tail) == 1:
                    lead = tail[0]
                else:
                    # Average all possible completions of this byte prefix.
                    codes = list(range(lo - 0xac00, hi - 0xac00 + 1))
    return text, tail, space, codes, lead, unfinished


def syllable_score(code, space, unfinished):
    onset = INITIALS[code // 588]
    vowel = VOWELS[code // 28 % 21]
    final = code % 28
    # Most closed syllables are quiet; n/l endings are the exceptions.
    if not unfinished and final not in (0, 4, 8):
        return 0.0
    if onset == 'ㄴ' and vowel in N_LOW_SCORE:
        value = N_LOW_SCORE[vowel] + 2.1 * space
    elif onset == 'ㄹ' and vowel == 'ㅏ':
        value = 2.5 + 0.4 * space
    else:
        value = (0.7 if vowel in 'ㅏㅓ' else 0.1) + 0.4 * space
        if onset == 'ㅎ':
            value -= 0.3
        if onset == 'ㅇ' and vowel in 'ㅕㅛ':
            value = -1.0
    return value - (0.3 if final == 4 else 0.0)


def predict(carry, doc, raw):
    if carry is None or carry['doc'] != doc:
        carry = dict(doc=doc, position=0, previous=b'', pending=b'',
                     space=False, ja=999, ko=999, vi=999,
                     word=b'', last_word='')
    text, tail, space, codes, lead, unfinished = decode_token(
        raw, carry['pending'], carry['space'])
    # Retain only the current word and the previous word, not the whole row.
    words = (carry['word'] + raw).split()
    last_word = carry['last_word']
    if raw[-1:].isspace():
        word = b''
        if words:
            last_word = words[-1].decode('utf8', 'ignore').lower()
    else:
        word = words[-1][-96:] if words else b''
        if len(words) > 1:
            last_word = words[-2].decode('utf8', 'ignore').lower()
    value = 0.0
    if lead:
        # EB covers the middle U+B000–BFFF slice of the Hangul block.
        value = 2.1 if lead == 0xeb else -0.3
        value += 1.2 * space
    elif codes:
        count = 1 if unfinished else len(codes)
        # Average syllable scores, then attenuate merged multi-syllable tokens.
        value = sum(syllable_score(c, space, unfinished) for c in codes) / (
            len(codes) * count)

    if raw == '、'.encode() and carry['ja'] < 64:
        value = -0.34
    elif raw == b',' and carry['ko'] < 64:
        value = -0.60
    if carry['vi'] < 48 or VIETNAMESE.search(text):
        if raw == b' ra':
            # Lexicalized 'happen/take place' is weaker than directional 'out'.
            value = 0.3 if last_word in ('xảy', 'diễn') else 4.2
        elif raw == b' ta':
            # chúng ta is the compound pronoun 'we'.
            value = 0.7 if last_word == 'chúng' else 4.5
        elif raw == ' rồi'.encode():
            value = 1.49
    position, previous = carry['position'], carry['previous']
    if position == 0:
        if raw == b'Title':
            value = -0.367
        elif raw == b'<?':
            value = 0.501
    elif position == 1:
        if previous == b'Title' and raw == b':':
            value = -5.815
        elif previous == b'<?' and raw == b'php':
            value = -1.548
    carry.update(position=position + 1, previous=raw, pending=tail,
                 space=space if tail else False, word=word,
                 last_word=last_word,
                 ja=0 if JAPANESE.search(text) else carry['ja'] + 1,
                 ko=0 if codes or lead else carry['ko'] + 1,
                 vi=0 if VIETNAMESE.search(text) else carry['vi'] + 1)
    return carry, float(value)


def step(carry, prefix, upstream):
    return predict(carry, prefix.document_ids[-1], prefix.token_bytes[-1])

"""Approximate a lexical variable / data-type signal.

A whole 'variable' is moderately positive; finishing it from smaller pieces
is much stronger. This includes several non-English spellings. Data-type
phrases, nominal -able words, and weaker detached -able/-ible endings
also contribute. Parameter descriptions,
and 'of' after parameter or arithmetic relation words, are negative.
Other positions are left at zero. Only a short, document-local text tail
is retained; no token-id lookup table is used.
"""
import re
import unicodedata

READS = ()


def activation(before, token):
    if not token:
        return 0.0
    text = before + token
    low = token.casefold().strip()
    m = re.search(r'([a-z]+)\s*\Z', before.casefold())
    previous = m[1] if m else ''

    if low == 'of':
        if previous in {'parameter', 'parameters', 'argument', 'arguments'}:
            return -1.4
        if previous == 'multiple':
            return -1.3
        if previous == 'exponent':
            return -2.1

    for term in ('变量', '變數', '변수', '変数'):
        if text.endswith(term) and not before.endswith(term):
            if term in token or term in {'变量', '變數'}:
                return 1.6
            return 5.3
    if re.search(r'переменн(?:ая|ый|ые|ых|ую|ой|ое|ыми)\Z', text.casefold()):
        return 4.2

    # Accent-insensitive Romance spellings: variável, variáveis, variabile.
    plain = ''.join(c for c in unicodedata.normalize('NFKD', text.casefold())
                    if not unicodedata.combining(c))
    m = re.search(r'([a-z]+)\Z', plain)
    word = m[1] if m else ''
    if re.fullmatch(r'(multi|uni|hyper)?variables?', word):
        if 'variable' not in low:
            if len(low) > 5:
                return 1.05
            return 7.0 if word.startswith(('multi', 'uni')) else 4.8
        if low in {'variable', 'variables'} and token[:1].isspace():
            if previous in {'random', 'free', 'assign', 'define', 'denote',
                            'changing', 'change'}:
                return 2.5
            return 1.55
        return 1.05
    if re.fullmatch(r'vari(?:ab|ablen|abile|abili|avel|aveis)', word):
        return 4.8

    if low in {'type', 'types', '类型', '型'}:
        if previous == 'data' or before.endswith(('数据', '資料', 'データ')):
            return 3.0
        if previous == 'return' or before.endswith('返回'):
            return 1.9
        if previous == 'reference':
            return 2.5
    if low == 'parameter':
        return -1.0 if previous in {'required', 'optional', 'query'} else -0.15

    # Financial obligations/claims and work products, with productive -able.
    if word in {'payable', 'payables', 'receivable', 'receivables'}:
        return 2.4 if word in low else 3.6
    if word in {'deliverable', 'deliverables'}:
        return 5.0
    if token.casefold() in {'able', 'ables', 'ible', 'ibles', 'iable'}:
        return 0.35
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = b'' if carry is None or carry[0] != doc else carry[1]
    before = tail.decode('utf-8', errors='ignore')
    combined = tail + prefix.token_bytes[-1]
    text = combined.decode('utf-8', errors='ignore')
    # Decode together so that split multi-byte characters are recognized.
    token = text[len(before):]
    return (doc, combined[-160:]), activation(before, token)

"""A sparse collection of local markup and code recognizers.

Positive rules cover decimal HTML quotes/>, selected tags, PHP openers,
Go test-start markers, templates, citation attributes, triple-tilde markers
and middle-dot pairs. PHP openers are stronger at the immediate start of a document. Negative rules
cover a few constructor, decorator, JavaDoc and TeX-like command prefixes.
All other positions get zero; other lexical/private-font effects are omitted.
Double-quote references are weaker after a space. Only the last 60
characters are carried, reset at document boundaries.
