import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail = ''
    else:
        tail = carry[1]
    token = prefix.token_strings[-1]
    text = tail + token
    value = 0.0
    tag = re.search(r'</?([A-Za-z]+)$', text)
    starts_tag = re.search(r'</?$', tail) or token.startswith('<')
    if token.isdigit():
        entity = re.search(r'&#(\d+)$', text)
        if entity:
            # Decimal encodings of double quote, apostrophe and greater-than.
            value = {'34': 3.0, '39': 1.85, '62': 2.9}.get(entity[1], 0.0)
            if entity[1] == '34' and text.endswith(' &#34'):
                value = 2.4
