        value = 3.7 if tail == '<?' else 0.4
    elif token == ' RUN' and tail.endswith('==='):
        value = 2.8
    elif token == 'ref' and tail.endswith('){'):
        value = 1.1
    elif tag and starts_tag:
        name = tag[1]
        if name in {'pre', 'PRE', 'details'}:
            value = 2.9
        elif name == 'dt':
            value = 1.15
        elif name == 'html':
            value = 0.6
        elif name == 'Project':
            value = 1.4
        elif name.isupper() and len(name) > 1:
            value = 1.3
    elif token == 'construct' and tail.endswith('__'):
        value = -1.0
    elif token == 'math' and tail.endswith('ensure'):
        value = -1.25
    elif token == ' a' and tail.endswith('---'):
        value = 0.9
    elif token == '~\n' and tail.endswith('~~'):
        value = 1.4
    elif token == '··':
        value = 2.1
    elif token == ' include' and tail.endswith('{%'):
        value = 2.8
    elif token == '_' and tail.endswith('<%'):
        value = 2.5
    elif token == '%-' and tail.endswith('{'):
        value = 0.8
    elif token == 'mock' and tail.endswith('@'):
        value = -2.1
    elif token in {'code', 'link'} and tail.endswith('{@'):
        value = -0.5
    elif token == 'foot' and tail.endswith('\\'):
        value = -1.4
    elif token == 'notes' and tail.endswith('\\foot'):
        value = -0.9
    elif token == 'object' and tail.endswith('\\'):
        value = -2.7
    return (doc, text[-60:]), value

