"""Candidate v7: a short list of tight, readable triggers; zero everywhere else.

Each rule fires on one token, given the text just before it. The values are the
typical activation seen for that trigger on training text (in nats-scale units)."""

READS = ()

# Tag names that show up right after "<" or "</" in HTML/XML/markup
MARKUP_NAMES = ("details", "FILE", "FONT", "PRE", "pre", "VERSION", "CODE", "DOCUMENT", "ROLE")


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    cur = toks[-1]
    p1 = toks[-2] if len(toks) >= 2 else ""      # previous token, as written
    before = "".join(toks[-4:-1])                # the three tokens before this one
    prev = p1.strip()
    v = 0.0
    if cur == " RUN" and prev == "===":
        v = 2.8                      # Go test log header: "=== RUN   TestName"
    elif cur == "FAIL" and prev == "---":
        v = 1.4                      # test-runner status word: "--- FAIL"
    elif cur.isdigit() and before.endswith("&#3"):
        v = 2.0                      # 2nd digit of a numeric entity &#3x; (&#39; &#34;)
    elif cur.isdigit() and before.endswith("&#x4"):
        v = 2.5                      # 2nd digit of &#x4x; (&#x40;)
    elif cur.strip() in MARKUP_NAMES and prev in ("<", "</"):
        v = 2.8                      # markup tag name: <details>, </FILE, <pre>
    elif cur == "php" and prev == "<?":
        v = 2.5                      # PHP open tag <?php
    elif cur == "ref" and p1 == "){":
        v = 1.15                     # pandoc cross-reference: (#F1){ref-type="fig"}
    elif cur == "foot" and p1.endswith("{\\"):
        v = -1.5                     # LaTeX \footnotesize inside a table
    elif cur == "notes" and p1 == "foot":
        v = -0.9
    elif cur == "object" and p1.endswith("\\"):
        v = -2.7                     # LaTeX \object{...}
    elif cur == "Illuminate" and p1.endswith("\\"):
        v = -3.5                     # PHP namespace \Illuminate\...
    elif cur == "mock" and prev == "@":
        v = -2.4                     # python decorator @mock_...
    elif cur == "_" and prev == "%":
        v = 2.5                      # JSP/ERB opener <%_
    return None, float(v)

