"""Predicts layers.1.mlp.down_proj:664, a small MLP feature in layer 1.

It fires mainly on the word "of" in a partitive after a quantifier:
"all of the ...", "most of them", "much of ...". The size depends on the
quantifier: "all" about +2, "most" and "much" about +1, "many", "none" and
"both" about +0.4, "some" about +0.3. Other quantifiers such as "half",
"majority", "part" and "one" give about 0, so they are left out.

It is negative on a few phrases: a relative pronoun right after a plural
pronoun ("those who", "them that"), and a name completion inside a fixed
phrase ("Great Britain", "Lord Jesus"). Everything else is predicted as 0.

The program reads only the previous and the current token, and it treats a
document boundary as the start of text.
"""

READS = ()

# Partitive quantifier before " of" -> predicted activation on that " of".
QUANTIFIER_OF = {
    "all": 2.0, " all": 2.0, " All": 2.0, "All": 2.0,
    "most": 1.0, " most": 1.0, " Most": 1.0, "Most": 1.0,
    " much": 1.0, " Much": 1.0,
    " many": 0.4, " none": 0.4, " both": 0.4,
    " some": 0.3, " Some": 0.3,
}
RELATIVE = {" who", " that", " which", " qui"}
PLURAL_PRONOUN = {" those", " them", " ones", "those", "them"}
NAME_COMPLETION = {" Britain", " Christ", " Jesus", " God"}
NAME_CONTEXT = {" Great", "reat", " Lord", " Jesus", "Lord"}


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    same_doc = len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2] if same_doc else ""

    if cur == " of":
        return carry, QUANTIFIER_OF.get(prev, 0.0)
    if cur in RELATIVE and prev in PLURAL_PRONOUN:
        return carry, -0.8
    if cur in NAME_COMPLETION and prev in NAME_CONTEXT:
        return carry, -1.5
    return carry, 0.0

