"""A spelling-fragment detector, not a detector of word meanings.

Positive responses mark real/rear, short tokens ending in real, and
vowel-prefixed rea/ree/ria/rie fragments ending in l/r. Splitting rea
or ree...l across tokens gives the strongest positives. Related vowel
and liquid continuations give smaller positives; r-vowel-v fragments
and cross-token rul give negatives. Transliteration excludes Han and
Hangul. Only the previous token is remembered, reset for each document.
"""
import re
import unicodedata
from functools import lru_cache
from anyascii import anyascii

READS = ()


@lru_cache(maxsize=16384)
def spelling(text):
    names = [unicodedata.name(c, '') for c in text if c.isalpha()]
    if any('CJK' in n or 'HANGUL' in n for n in names):
        return '', False
    return anyascii(text).lower(), all('LATIN' in n for n in names)


@lru_cache(maxsize=65536)
def response(previous, current, latin):
    word = current.strip()
    if latin:
        if word == 'real':
            return 1.09
        if word == 'rear':
            return 3.29
        # Vowel prefixes avoid treating complete words like trial as fragments.
        if (len(word) <= 7 and word.endswith('real') or
                re.fullmatch(r'[aeiou]*r[ei][ae][lr]+', word)):
            return 2.7
        if re.fullmatch(r'rell[as]?', word):
            return 2.5
        if re.fullmatch(r'r[aeiouy]v', word):
            return -1.3
    tail = previous[-3:]
    joined = tail + current
    for m in re.finditer(r'r([aeiouy])([a-z])', joined):
        if not m.start() < len(tail) < m.end():
            continue
        first, second = m.groups()
        rest = joined[m.end():]
        if len(rest) > 2 and not rest.startswith("l'"):
            continue
        if first == 'e' and second == 'a':
            if rest.startswith(('l', 'r')):
                return 5.3
            if rest.startswith('n'):
                return 3.5
            if not rest:
                return 3.9
        if first == 'e' and second == 'e' and rest.startswith('l'):
            return 4.8
        if first in 'ei' and second in 'aeiou':
            return 0.43
        if second == 'l' and first != 'u':
            return 2.1 if first == 'e' and rest.startswith('l') else 0.41
        if second == 'v' or (first == 'u' and second == 'l'):
            return -0.15 if rest else -0.85
    return 0.0


