    core = s[1:] if attached else s
    if len(core) > 1 and core.endswith('的'):
        core = core[:-1]
    g = meanings(core)
    value = 0.0
    if len(core) > 1 and (re.search(_TOPIC, g) or core.startswith('对于')):
        value += 0.8
    elif core == '对' or (not g and core.startswith('对')):
        value += 0.48
    if core == '就':
        value += 0.48
    if core == '在':
        value += 0.12
    if core.startswith('因') and (re.search(r'\bbecause\b', g) or
                                  core.startswith('因为')):
        value += 0.4 if len(core) > 1 else 0.18
    if core == '因此':
        value += 0.35
    if len(core) > 1 and re.search(r'\b(in order to|so that)\b', g):
        value += 0.2
    if len(core) > 1 and re.search(r'\b(to state|to point out|to leak out)\b', g):
        value += 0.5
    if core in {'等', '等等', '等人'}:
        value += 0.38
