    # A character can be split across byte-level tokens.
    decoded = (raw + data).decode('utf-8', errors='ignore')
    if '\ufffd' in s and decoded.endswith('初'):
        value = -11.7
    if '\ufffd' in s and decoded.endswith('川'):
        value = -4.0
    if leading and s and set(s) <= {'·'}:
        value = -2.5
    if leading and len(s) >= 2 and set(s) <= {'^'}:
        value = -2.7
    if not previous:
        if s == 'from':
            value = 2.02
        if s in (';', '{', '«', '\\"'):
            value = -1.7
    leading = leading and all(c.isspace() or c in '·^' for c in s)
