"""A partial even-number-context detector.

Predict positive responses on even item labels, especially 2, and on a
nine following an even decimal digit.  Line placement distinguishes list
labels from numerals inside prose or code.  Include lettered/Roman labels,
Chinese even numerals, and negative responses on dates after even-numbered
English months.  Leave other tokens, including lexical first-token effects,
at zero rather than memorizing their identities.
"""
import calendar
import re
import unicodedata

READS = ()
NINE = (0.14, -0.02, 0.36, -0.10, 0.18,
        -0.10, 0.39, -0.11, 0.22, -0.06)
CHINESE_EVEN = dict(zip('二四六八', (2, 4, 6, 8)))
MONTHS = {name.lower(): i for i in range(1, 13)
          for name in (calendar.month_name[i], calendar.month_abbr[i])}
LINE = re.compile(r'(?:^|\n|\\n)[\s#>*•+\-]*$')
SENTENCE = re.compile(r'[.!?。！？;；][ \t]*$')
LABEL_WORD = re.compile(r'(?i)(?:step|case|section|chapter|article|part)\s*$')
MONTH_END = re.compile(r'([A-Za-z]+)\.?\s+$')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, text = '', ''
    else:
        _, previous, text = carry
    token = unicodedata.normalize('NFKC', prefix.token_strings[-1])
    number = re.search(r'([0-9]+)$', text)
    value = 0.0

    if token == '9' and previous in tuple('0123456789'):
        digit = int(previous)
        value = NINE[digit]
        if number:
            length = len(number[1])
            before = text[:number.start()]
            if LINE.search(before) and digit % 2 == 0:
                value += 0.15
            if length >= 3:
                value *= 0.8
            if length > 6:
                value *= 0.3

    elif token.startswith(('.', ')', '、', ':')):
        chinese = previous[-1:] in CHINESE_EVEN
        if number or chinese:
            digits = str(CHINESE_EVEN[previous[-1]]) if chinese else number[1]
            before = text[:-len(previous)] if chinese else text[:number.start()]
            last, length = int(digits[-1]), len(digits)
            line = bool(LINE.search(before))
            sentence = bool(SENTENCE.search(before))
            space = bool(before[-1:].isspace())
            bracket = before.endswith('(')
            bracket_line = bracket and bool(LINE.search(before[:-1]))
            even = last % 2 == 0
            context = 3 if line else 2 if sentence else 1 if space else 0
            if token.startswith(('.', '、')):
                if last == 2:
                    value = (0.12, 0.24, 0.62, 1.04)[context]
                elif last in (4, 6, 8):
                    value = (0.04, 0.11, 0.36, 0.71)[context]
                elif last == 0:
                    value = 0.40 if line and length == 2 else 0.04
                else:
                    value = 0.10 if line and last in (3, 5) else 0.0
                    if last == 1:
                        value = -0.03
                if length == 2 and last != 0:
                    value *= 0.54 if even else 0.5
                elif length > 2:
                    value = 0.0
                if chinese:
                    value = 1.2 if line or sentence else 0.55
            elif token.startswith(')'):
                if even:
                    strength = 1.2 if last == 2 else 0.75
                    factor = (1 if line else 0.75 if bracket_line else
                              0.7 if sentence else 0.34 if bracket else
                              0.25 if space else 0.0)
                    value = strength * factor * (0.4 if length > 1 else 1)
                # Attached algebraic operators are not item delimiters.
                tail = token[1:]
                if tail and not tail.isspace() and tail != '.':
                    value *= 0.1
            else:
                value = 0.26 if last == 2 else 0.10 if even else -0.03
                if LABEL_WORD.search(before):
                    value *= 1.8
        else:
            label = previous.strip().lstrip('(')
            before = text[:-len(previous)] if previous else text
            line = bool(LINE.search(before))
            if label in ('a', 'c', 'e', 'A', 'C', 'E'):
                value = 0.68 if line else 0.38 if label.islower() else 0.20
            elif label.lower() in ('i', 'ii', 'iii', 'iv', 'v'):
                value = 0.4 if line else 0.2
            if token.startswith(':'):
                value *= 0.2
    elif previous.endswith('第二') and token in ('章', '条', '节', '部分'):
        value = 0.75

    # The first date digit after June/August is especially negative.
    if len(token) == 1 and token in '0123456789':
        month = MONTH_END.search(text)
        month = MONTHS.get(month[1].lower(), 0) if month else 0
        if month and month % 2 == 0:
            value = -0.30 if month in (6, 8) else -0.16
            if token == '1':
                value *= 1.25
            elif token not in '23':
                value *= 0.7
    return (doc, token, (text + token)[-160:]), float(value)

