READS = ()
END = {".", ")", "）", "、", ":"}
EVEN = {"2", "4", "6", "8"}

def step(carry, prefix, upstream):
    toks = prefix.token_strings
    docs = prefix.document_ids
    n = len(toks)
    cur = toks[-1]
    if cur in END and n >= 2 and docs[-2] == docs[-1]:
        k = n - 2
        label = ""
        while k >= 0 and docs[k] == docs[-1] and toks[k].isdigit() and len(label) < 3:
            label = toks[k] + label
            k -= 1
        if not label and len(toks[n - 2]) == 1 and toks[n - 2].isalpha():
            label = toks[n - 2]
            k = n - 3
        at_line_start = k < 0 or docs[k] != docs[-1] or "\n" in toks[k]
        if label.isdigit() and label[-1] in "02468":
            if len(label) == 1:
                if label in EVEN:
                    if at_line_start:
                        return carry, 1.0
                    return carry, 0.25 if toks[k].strip() == "" else 0.1
            elif at_line_start:
                return carry, 0.5
        if label.isalpha() and at_line_start:
            return carry, 0.3
    if cur == "9" and n >= 2 and docs[-2] == docs[-1] and toks[-2] in "02468":
        return carry, 0.25
    if cur == "··":
        return carry, -0.4
    return carry, 0.0

