"""Sparse orthographic approximation, not a single semantic category.

It distinguishes Cyrillic po-like and pi-like fragments and recognizes a few
Chinese spelling, persistence/support and accompaniment words, plus poz/pinyin.
풍 and doubled middots give positive responses. Split UTF-8 characters are
completed before matching; state resets between documents. Other input gives
zero, leaving the component's diffuse background activity unexplained.
"""
import codecs
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        decoder = codecs.getincrementaldecoder('utf-8')('ignore')
        word = ''
    else:
        _, decoder, word = carry
    split_character = bool(decoder.getstate()[0])
    text = decoder.decode(prefix.token_bytes[-1])
    before = word if text[:1].isalpha() else ''
    token = text.strip().lower()
    match = re.search(r'[^\W\d_]+$', word + text)
    word = match.group()[-32:].lower() if match else ''
    value = 0.0

    # Short o-initial pieces in Cyrillic po-, obo- and podo- words.
    if token in ('оз', 'ож', 'ог', 'ой', 'о'):
        if before in ('п', 'об', 'под'):
            value = -4.6 if token in ('оз', 'о') else -3.0
        elif token in ('оз', 'ож') and before.endswith(('п', 'б', 'в')):
            value = -1.5
        elif before == 'произ' and token == 'о':
            value = -4.8
    if before in ('п', 'оп', 'нап') and token in ('ин', 'ит'):
        value = 2.8 if before == 'нап' and token == 'ит' else 1.3
    if before == 'по' and token in ('с', 'х', 'ц', 'ш', 'є'):
        value = -0.8
    if before.endswith('п') and token == 'ос':
        value = -0.8
    if token == 'поз':
        value = -2.5
    if before.endswith('пож') and token in ('ал', 'ел'):
        value = -2.6 if token == 'ал' else -1.5
    if before.endswith('поз') and token == 'и':
        value = -4.0 if before == 'поз' else -1.5
    if before == 'поп' and token == 'ы':
        value = -3.5

    # Latin spellings of the same po-z sequence, and pinyin.
    if token == 'oz' and before.endswith('p'):
        value = -2.4
    if token == 'poz':
        value = -1.8
    if token == 'inyin' and before.endswith('p'):
        value = -3.7

    # 拼/拚: piece together/spell; 坚持: persist; 陪: accompany; 支持: support.
    # Separate spelling responses, not a claim about all their synonyms.
    if token.startswith(('拼', '拚')):
        value = -7.6 if token in ('拼', '拼音', '拚') else -4.0
        if split_character:
            value = -11.0
        if token == '拼命':
            value = -1.1
    elif token in ('坚持', '堅持', '要坚持'):
        value = -3.0
    elif token.startswith('陪'):
        value = -1.5 if token == '陪伴' else -2.8
    elif token == '支持':
        value = -0.4

    if text.endswith('풍'):
        value = 3.6
    if text == '··':
        value = 0.98
    return (doc, decoder, word), value

programs.haiku:
"""Layer 1, MLP down-projection, component 673: a "start of a reported or printed message" detector.

The component writes into the residual stream with a sign that is mostly negative exactly where
a piece of text is being introduced as someone's words or as program output:

- Chinese news prose reports speech with verbs such as 表示 / 指出 / 强调 / 介绍 / 讲解 / 透露 /
  认为 (the verb itself is negative), and the comma right after such a verb, which opens the
  reported content, is strongly negative.
- News-event words (现场, 首先, 随后, 会上, 同学们, 大家 ...) are negative too.
- A heredoc marker `EOF` (the start of a shell text block) is negative.
- In code, the string argument of a print-like call (print("...), echo('...), printf(`...`)
  is negative at its opening quote, and other string literals opened by "(" are weakly negative.

Everything else is predicted as 0 (the component's typical activation is small and noisy).
The magnitudes are the average activation observed for each rule on training rows.
"""

READS = ()

REPORT_VERBS = {"表示", "指出", "强调", "介绍", "讲解", "透露", "认为"}
REPORT_COMMAS = {"，", ","}
EVENT_WORDS = {
    "现场", "首先", "随后", "会上", "先后", "纷纷", "据悉", "据了解",
    "同学们", "大家", "党员干部", "致辞", "颁奖", "签约仪式", "参观",
}
PRINT_CALLS = {"print", "printf", "println", "echo", "puts"}
QUOTES = "\"'`"


def opens_string(token):
    """True for a token that opens a string literal: a quote, or "(" followed by a quote."""
    return token[:1] in QUOTES or (len(token) > 1 and token[0] == "(" and token[1] in QUOTES)


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1].strip()
    prev = prefix.token_strings[-2].strip() if len(prefix) > 1 else ""
    if tok in REPORT_VERBS:
        return None, -0.30
    if tok in EVENT_WORDS:
        return None, -0.57
    if tok == "EOF":
        return None, -0.66
    if prev in REPORT_VERBS and tok in REPORT_COMMAS:
        return None, -0.58
    if prev in PRINT_CALLS and opens_string(tok):
        return None, -0.27
    if len(tok) > 1 and tok[0] == "(" and tok[1] in QUOTES:
        return None, -0.07
    return None, 0.0

programs.sol:
"""A mostly lexical indefinite-article detector with local grammatical cues.

English 'a' is strongest after location/role prepositions, creation verbs,
negation and actions, weaker after possession or giving. Mathematical uses
of the letter and Romance-language prepositional uses are damped. Related
European articles and 'one of' are additional positive cues. Slavic 'on'
and repeated middle-dot leaders are separate lexical responses. A small
negative correction handles the first token, where no context is available.
Only the preceding 120 characters and immediately preceding token are kept.
"""
import re
import wordnet

READS = ()

COPULAS = set('is am was be been being'.split())
HAVE = set('has have had having'.split())
CREATE = set('make build create form generate construct develop design'.split())
ACTION = set('do take use get'.split())
NEED = set('need require want'.split())
GIVE = set('give offer provide'.split())
ROMANCE = set('que de del los las el la le il di da della degli dei nel nella '
              'por para uma una uno'.split())
GERMAN = set('der die das den dem des und ist sind nicht mit sich auch zu im '
             'von auf als für wird wurde werden ein eine einer einem'.split())
PORTUGUESE = set('que de do da dos das em para uma um não os as'.split())
ARTICLES = {'un', 'una', 'uno', 'um', 'uma', 'une'}


def predict(token, previous, context, first):
    if '··' in token:
        return -1.68
    word = token.strip()
    if first:
        if token.startswith('<|'):
            return 0.0
        if word.isalpha():
            return -0.37 if word[0].isupper() else -0.20
        return -0.12 if word.isdigit() else -0.25
    p = previous.strip().lower()
    if token in (' a', ' an'):
        value = 0.35 if token == ' a' else 0.01
        bases = set(wordnet.base_forms(p))
        if p in COPULAS:
            value -= 0.08
        elif p in {'are', 'were'}:
            value -= 0.32
        elif p in HAVE:
            value -= 0.16
        elif p in {'in', 'into', 'at', 'as', 'by', 'within'}:
            value += 0.15
        elif p in {'with', 'to', 'for', 'from'}:
            value -= 0.10
        elif p == 'of':
            value += 0.07
        elif p == 'or':
            value += 0.20
        elif p in {'that', 'this', 'any', 'all', 'each', 'every'}:
            value -= 0.24
        elif bases & CREATE:
            value += 0.22
        elif bases & ACTION:
            value += 0.10
        elif bases & NEED:
            value -= 0.10
        elif bases & GIVE:
            value -= 0.43
        elif p in {'not', 'without', 'never'}:
            value += 0.35
        if not p.isalpha():
            value -= 0.10
        if previous.isspace() or p in {'=', '+', '-', '*', '/', '^', ':'}:
            value -= 0.20
        words = set(re.findall(r'[^\W\d_]+', context.lower()))
        if len(words & ROMANCE) >= 2:
            value -= 0.34
        if len(re.findall(r'\b[a-dxyz]\b|[=^∈]', context)) >= 3:
            value -= 0.12
        return value
    if word.lower() in ARTICLES and not word.isupper():
        words = set(re.findall(r'[^\W\d_]+', context.lower()))
        if len(words & GERMAN) >= 2:
            return -0.10
        if not token.startswith(' ') and previous[-1:].isalnum():
            return 0.0
        if word.lower() in {'un', 'um'} and (word[0].isupper()
                                           or not token.startswith(' ')):
            return 0.25
        return 0.74
    if token in {' ein', ' eine', ' einen', ' einem', ' einer', ' een'}:
        return 0.43 if token in {' ein', ' een'} else 0.27
    if token in {' на', ' На', 'На'}:
        return 1.04 if token == ' на' else 1.40
    if token == ' na':
        words = set(re.findall(r'[^\W\d_]+', context.lower()))
        return -0.10 if len(words & PORTUGUESE) >= 2 else 0.83
    if token == ' of' and p == 'one':
        return 1.04
    if token in {' de', ' des', ' dos', ' das'} and p in ARTICLES:
        return 0.65
    if token in {' A', 'A'}:
        return 0.06
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous, context = ('', '') if first else carry[1:]
    token = prefix.token_strings[-1]
    value = predict(token, previous, context, first)
    return (doc, token, (context + token)[-120:]), value

