"""Layer-1 MLP down_proj component 674: indefinite articles ('a', 'un', 'ein', ...).

Fires on the indefinite article that opens a noun phrase: English 'a' (strongest after
verbs like make/do/create/write, weaker after provide/offer), and its equivalents in other
languages (un/una/une, ein/eine/een, uno, um). Also on 'of' after a quantifier ('one of',
'each of'). Strongly negative on the first token of each document, and on runs of
middle-dot leader characters.
"""
DOC_START = -0.24
DOT_LEADER = -1.7
A_AFTER_MAKING = 0.44        # 'a' right after make/do/create/write, or as/not/without/in/of
A_AFTER_PROVIDING = -0.17    # 'a' right after provide/offer, or are
A_OTHER = 0.30               # any other 'a'

ARTICLE = {" un": 0.61, " una": 0.74, " une": 0.69, " uno": 0.37, " ein": 0.44, " eine": 0.27,
           " een": 0.39, " um": 0.34, " na": 0.61, " на": 1.04, " На": 1.34}
OF_AFTER_QUANT = 0.6
MAKING_WORDS = {"make", "made", "do", "create", "write", "take", "become",
                "as", "not", "without", "in", "of"}
PROVIDING_WORDS = {"provide", "provides", "providing", "offer", "offers", "are"}
QUANTIFIERS = {" one", " each", " any", " some", " none", " two", " many", " which", " both",
               " out", " most", "One", " several"}
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    # First token of each document (also the first token of a row): strongly negative.
    if len(prefix.token_strings) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, DOC_START
    before = prefix.token_strings[-2]
    if token == "··":
        return None, DOT_LEADER
    if token == " of" and before in QUANTIFIERS:
        return None, OF_AFTER_QUANT
    if token == " a":
        if before.strip() in MAKING_WORDS:
            return None, A_AFTER_MAKING
        if before.strip() in PROVIDING_WORDS:
            return None, A_AFTER_PROVIDING
        return None, A_OTHER
    return None, ARTICLE.get(token, 0.0)

"""Counting-expression detector for layer 1, MLP down_proj component 675.

What it does. The component goes negative on the word that completes a count written in
mathematics or code, and is near zero almost everywhere else. The triggers are:
  - a count noun right after a number or a one-letter variable: "12 ways", "n times",
    "k steps", "32-bit", "n-fold", "10 students";
  - an ordinal right after a variable or number: "n-th", "k-th", "50th";
  - a factorial sign right after a number or variable: "n!", "25!";
  - the "1" or "2" of an index offset after a sign and a variable: "n-1", "k+1", "i+1".
The response is stronger when a counting or probability problem is under way (words such
as "how many", "number of", "ways", "permutation", "probability" in the last 60 tokens).
Everything else predicts 0.
"""

import re

READS = ()

COUNT_NOUNS = {
    "times", "ways", "steps", "terms", "items", "bits", "digits", "rows", "boxes",
    "beads", "cards", "students", "men", "parts", "lines", "different", "equations",
    "choices", "colors", "elements", "copies", "options", "-bit", "-digit", "-fold",
    "dimensional", "-dimensional",
}
ORDINALS = {"th", "-th", "nth", "ith", "-nth", "-ith"}
OFFSET_SIGNS = {"+", "-", "−"}
COUNTING_CUE = re.compile(
    r"how many|number of|ways|arrangement|permutation|combination|choose|factorial|count|"
    r"possible|distinct|expected|probability|sequence|binomial|subset|partition",
    re.IGNORECASE,
)

# Mean activation for each trigger, without and with a counting cue nearby.
VALUE = {"count": (-0.55, -1.2), "factorial": (-0.8, -3.7), "offset": (-0.15, -0.3), "index": (-1.0, -1.45)}


def _bare(text):
    return text.strip().strip("$()").strip()


def _is_number(text):
    return _bare(text).isdigit()


INDEX_VARS = set("nNkKijmM")


def _is_variable(text):
    bare = _bare(text)
    return len(bare) == 1 and bare.isalpha()


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    docs = prefix.document_ids
    t = prefix.position
    cur = _bare(toks[t]).lower()
    prev_ok = t >= 1 and docs[t - 1] == docs[t]
    prev = toks[t - 1] if prev_ok else ""
    after_operand = prev_ok and (_is_number(prev) or _is_variable(prev) or prev.strip() in (")", "}"))
    kind = None
    if after_operand and (cur in COUNT_NOUNS or cur in ORDINALS):
        kind = "count"
    elif after_operand and cur == "!":
        kind = "factorial"
    elif cur in ("1", "2") and t >= 2 and docs[t - 2] == docs[t] and prev.strip() in OFFSET_SIGNS:
        kind = "index" if _bare(toks[t - 2]) in INDEX_VARS else ("offset" if _is_variable(toks[t - 2]) else None)
    if kind is None:
        return carry, 0.0
    cued = bool(COUNTING_CUE.search("".join(toks[max(0, t - 60):t])))
    return carry, float(VALUE[kind][1 if cued else 0])

