"""Approximate a local negative response to 常 (usual, regular, constant).

The isolated character and permanent-office terms respond most strongly.
Ordinary compounds respond less; long tokens and Japanese adverbs ending
in に attenuate the response. Three associated word forms outside Chinese
have smaller responses. No earlier context is used. The varied responses
to other word fragments, especially continuations of ch, are not modeled.
"""
READS = ()


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1].strip()
    word = text.casefold()
    value = 0.0
    if '常' in text:
        japanese_adverb = text.endswith('に')
        base = text[:-1] if japanese_adverb else text
        if base.endswith('的'):
            base = base[:-1]
        if base == '常':
            value = -7.0
        elif '常委' in base or base in {'常务', '常務'}:
            value = -5.5
        elif '常见' in base or '常見' in base or base == '通常':
            value = -1.5
        else:
            value = -2.8
        if len(base) > 2 and '常委' not in base:
            value *= 0.2
        if japanese_adverb:
            value *= 0.06
    elif word == 'often':
        value = -0.25
    elif word == 'thường':
        value = -1.8
    elif word == 'chang':
        value = -1.2
    return None, value

