FIELD_KEY = re.compile(
    r'(?:[{,]\s*|^\s+(?:\d+\t\s*)?)[A-Za-z_$][\w$]*$'
)
FOR_BINDING = re.compile(
    r'\bfor\b\s*\(?\s*(?:(?:var|let|const)\s+)?\w+\s*$'
