        if '\t' in s:
            return 6.2 if s == '\t' else 3.6
        if '\n' in s or '\r' in s:
            return 3.5 if s == '\n' else 2.0
        return 5.5
    if t.startswith('_') and len(t) > 1:
        return 5.0
