    if s == 'package':
        return 13.2
    if s in ('import', '#include'):
        return 7.6
    if s == ':':
        return -0.6
    if t == ',':
        return 2.7
    if len(t) > 1 and len(set(t)) == 1 and not t[0].isalnum():
        return 5.0
    if t.lower() in ('a', 'an', 'the'):
        return 5.6
    if t.lower() in ('is', 'are', 'was', 'were', 'has', 'have', 'had'):
        return 2.2
    if t.lower() in ('and', 'or', 'but', 'if', 'so', 'as'):
        return 2.7
