    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    token_id = prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        return (doc, token_id, True, s[-200:]), opening_value(s)
    _, first, opening, recent = carry
    opening = opening and token_id == first
    value = 0.0
    t = s.strip()
    if opening:
        value = opening_value(s)
