READS = ()
# Common second characters in Chinese compounds beginning with 推.
PUSH_SUFFIXES = frozenset('出進进廣广動动薦荐理断移行')
PUSH_BYTES = '推'.encode('utf-8')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        line, blank, prose, tail, pushed = '', 0, False, b'', 0
    else:
        _, line, blank, prose, tail, pushed = carry
    token = prefix.token_strings[-1]
    raw = prefix.token_bytes[-1]
    joined = tail + raw
    split_push = '推' not in token and PUSH_BYTES in joined
    value = 0.0
