        if token.strip() == '推' or split_push:
            value = -14.0 if split_push else -10.5
        elif '推薦' in token:
            value = -6.0
        elif '推出' in token or '推荐' in token:
            value = -4.1
        else:
            value = -2.8
    elif pushed and token[:1] in PUSH_SUFFIXES:
        value = -2.8 * pushed
    if '\n' in token:
        windows = '\r' in token
        token = token.replace('\r', '')
        lead = token.split('\n', 1)[0]
        title = (line + lead).strip()
        words = title.split()
        clean = not any(c in title for c in '.,;!?{}[]<>/\\=#*`')
        dated = (title[:1].isdigit()
                 and any(c.isascii() and c.isalpha() for c in title))
        heading = (title[:1].isascii()
                   and (title[:1].isupper() or dated)
                   and clean and len(title) < 100)
        if blank and heading:
            value = 2.6 if prose else 1.5
            if len(words) > 6:
                value *= 0.5
            if line.startswith((' ', '\t')):
                value *= 0.3
            if ':' in title:
                value *= 0.5
            if blank >= 2 and len(words) <= 3:
                value *= 1.35
            if token.endswith('\n\n'):
                value *= 0.08 if not lead else 0.3
            elif lead == ' ':
                value *= 1.3
            elif lead == '  ':
                value *= 0.4
        if windows:
            value *= 0.1
        parts = token.split('\n')
        for part in parts[:-1]:
            ended = (line + part).strip()
            if ended:
                prose = ended.endswith(('.', '!', '?'))
                blank = 0
            else:
                blank += 1
            line = ''
        line = parts[-1]
    else:
        line = (line + token)[-200:]
    pushed = 2 if split_push else int(token.endswith('推'))
    return (doc, line, blank, prose, joined[-2:], pushed), value

