"""layers.1.mlp.down_proj:678, a two-part program.

(1) Section headings. The component fires on the single newline that ends a short
    heading-like line (capitalised, no final punctuation) when the line sits alone
    between blank lines, and the paragraph just before it was long. Typical cases:
    "Introduction\\n", "Conclusions\\n", "Early life\\n" after a body paragraph.
    The stronger the preceding paragraph and the more the line looks like a title,
    the larger the value.
(2) The Chinese character 推 (as in 推进, 推出, 推荐). The bare token 推 drives the
    component strongly negative; words containing 推 are moderately negative.
"""

READS = ()

END_PUNCT = set(".!?,;:)]}\"'")


def _heading_value(line, prev_block):
    if not line or line[-1] in END_PUNCT:
        return 0.0
    upper = line[0].isupper()
    long_before = prev_block >= 200
    if upper and long_before:
        return 2.0
    if upper:
        return 0.6
    if long_before:
        return 0.3
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids
    tok = prefix.token_strings[-1]
    if carry is None or len(doc) < 2 or doc[-1] != doc[-2]:
        carry = ("", True, 0, 0, "")
    cur, line_prev_blank, block, prev_block, last_tok = carry

    if tok == "推":
        value = -11.0
    elif "推" in tok:
        value = -4.0
    elif tok in ("进", "進") and last_tok == "推":
        value = -3.0
    else:
        value = 0.0

    if "\n" in tok:
        pieces = tok.split("\n")
        n = len(pieces) - 1
        for k in range(n):
            line = ((cur + pieces[0]) if k == 0 else "").strip()
            if not line:
                if block > 0:
                    prev_block = block
                block = 0
                line_prev_blank = True
            else:
                if n == 1 and line_prev_blank:
                    value = max(value, _heading_value(line, prev_block))
                block += len(line)
                line_prev_blank = False
        cur = pieces[-1]
    else:
        cur = cur + tok
    return (cur, line_prev_blank, block, prev_block, tok), value

