"""Approximate an opening-delimiter response using surface syntax.

Parentheses, square/curly brackets and generic-type angles usually receive
negative values. Attached words, quotes, operators and annotation markers
change their strength; same-token closings suppress it. Multiline openings
are stronger. Recent text distinguishes TeX, object literals, declarations
and code blocks, and disambiguates backslashes used in serialized code.
TeX delimiter-sizing commands and a backslash just after an opener also
have responses. The state is only the last token and 180 recent characters,
reset at document boundaries; this is not a bracket-stack parser.
"""
import re

READS = ()
OPENERS = '（([［{<'
CLOSERS = {'(': ')', '（': '）', '[': ']', '［': '］', '{': '}', '<': '>'}
DECLARATION = re.compile(r'\b(class|struct|namespace|interface|enum)\b[^;{}]*$')


def predict(token, previous, tail):
    if token == '\\' and previous.endswith(('{', '(', '[')):
        return -2.85 if previous.endswith('{') and '\\n' in tail else -0.75
    if previous.endswith('\\'):
        if token == 'left':
            return -1.04
        if token == 'right':
            return -0.24
        if token in ('big', 'bigg'):
            return -0.8

    # When several delimiters are fused, the last opening is the new one.
    index = max((token.rfind(c) for c in OPENERS), default=-1)
    if index < 0:
        return 0.0
    opening = token[index]
    after = token[index + 1:]
    if CLOSERS[opening] in after:
        return 0.0
    before = token[:index]
    spaced = token.startswith(' ')
    newline = '\n' in after
    word = any(c.isalnum() for c in after)
    quote = any(c in after for c in "\"'`")
    slash = '\\' in after
    tex = '$' in tail and '\\' in tail and '\\n' not in tail
    escaped_line = slash and not tex

