            if spaced and re.search(r'\bimport\s*$', tail):
                return -4.0
            return -2.5 if spaced else -2.0
        if word:
            return -0.15
        if quote:
            return -0.35 if spaced else -0.20
        if after.startswith('!'):
            return 0.3
        if after.startswith(('|', '&')):
            return 0.2
        if after.startswith(('-', '+')):
            return -0.33
        if before.endswith('\\'):
            return -0.1
        if token in ('(', '（'):
            return -0.65
        return -0.67 if spaced else -0.53

    if opening in '[［':
        if before.endswith('#') or after.startswith('@'):
            return 0.3
        if newline or (escaped_line and spaced):
            return -2.15 if spaced else -1.65
        if word:
            return -0.11
        if quote:
            return -0.16
        return -0.39

