import math
import re
from functools import lru_cache
import regex
from wordfreq import get_frequency_dict, top_n_list

READS = ()
SCRIPTS = [(regex.compile(r'\p{Script=' + script + '}'), language)
           for script, language in [('Latin', 'en'), ('Han', 'zh'),
               ('Hiragana', 'ja'), ('Katakana', 'ja'), ('Cyrillic', 'ru'),
               ('Arabic', 'ar'), ('Hangul', 'ko'), ('Devanagari', 'hi'),
               ('Greek', 'el'), ('Hebrew', 'he')]]

@lru_cache(maxsize=16)
def frequencies(language):
    return get_frequency_dict(language)

@lru_cache(maxsize=100000)
def frequency(word):
    language = next((lang for pattern, lang in SCRIPTS
                     if pattern.search(word)), 'en')
    mass = frequencies(language).get(word.lower(), 0)
    return max(0., math.log10(mass) + 9) if mass else 0.

COMPLETIONS = {}
for word in top_n_list('en', 50000):
    if word.isalpha():
        mass = frequencies('en').get(word, 0)
        for length in range(1, min(7, len(word))):
            beginning = word[:length]
            COMPLETIONS[beginning] = COMPLETIONS.get(beginning, 0.) + mass

