    " and": 1.0, " And": 0.65, "And": 0.65, "-and": 0.8, " AND": 0.8,
    " und": 1.4, " Und": 1.2, " et": 1.0, " y": 1.0, " e": 1.0, " и": 1.0,
    " och": 1.7, " og": 1.6, " و": 1.0, " và": 1.0, " și": 1.2, " és": 1.1,
    "://": 1.5, "和": 0.4,
