def first_token_value(tok):
    """Activation at a document's first token, which sees no context: depends on the token."""
    body = tok.lstrip(" ")
    if tok.startswith("<|") or not body:
        return 0.0                      # special tokens, blanks
    if body[0] in "\n\r\t":
        return -2.5                     # line breaks
    if body[0].isdigit():
        return -2.2                     # digits
    if not body[0].isalpha():
        return -0.8                     # punctuation
    if tok.startswith(" ") and not body[0].isupper():
        return -0.6                     # lowercase word continuing a sentence
    return 0.0                          # capitalised or unspaced word


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    at_start = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if at_start:
        return None, first_token_value(tok)
    if len(tok) >= 2 and set(tok) == {"·"}:
        return None, -7.8               # run of middle dots
    return None, CONJUNCTIONS.get(tok, 0.0)

