"""Predict short nasal-letter fragments, with a language-dependent sign.

Dictionary word frequencies vote for the surrounding language. Short Latin
n-fragments are negative in Romance text and positive in Turkish/Indonesian;
ordinary English text is mostly quiet. Arabic nun and its immediate diacritic
continuations are positive. Two exceptional surface patterns are an initial
'Title:' header and runs of centered dots. Individual lexical exceptions
are left unmodeled.
"""
import re
import unicodedata
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
LANGUAGES = ('en', 'fr', 'it', 'es', 'pt', 'ro', 'de', 'nl', 'tr', 'id')
ROMANCE = {'fr': -.5, 'it': -.3, 'es': -.2, 'pt': -.4, 'ro': -.9}
ARABIC_FORMS = 'ةىأإؤئيك'
PERSIAN_FORMS = 'پچژگکی'
ROMANIAN_LOCATION_PREPOSITIONS = {'în', 'in', 'din'}

@lru_cache(maxsize=50000)
def frequencies(word):
    return tuple(zipf_frequency(word, lang) for lang in LANGUAGES)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        scores = [0.] * len(LANGUAGES)
        previous, position, script_bias = '', 0, 0.
    else:
        _, scores, previous, position, script_bias = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    space = token != token.lstrip()
    scores = [s * .94 for s in scores]
    freq = (0.,) * len(LANGUAGES)
    latin_word = word.isalpha() and all(ord(c) < 700 for c in word)
    if len(word) >= 2 and latin_word:
        freq = frequencies(word)
        if space and max(freq) > 3:
            scores = [s + max(f - 3, 0.) ** 2 for s, f in zip(scores, freq)]
    if any(c in word for c in 'ğış'):
        scores[8] += 12
    lang = max(range(len(scores)), key=scores.__getitem__)
    language = LANGUAGES[lang]
    # Distinguish Arabic from Persian spellings in this shared script.
    script_bias = .95 * script_bias
    script_bias += sum(c in ARABIC_FORMS for c in word)
    script_bias -= sum(c in PERSIAN_FORMS for c in word)
    value = 0.
    plain = ''.join(c for c in unicodedata.normalize('NFD', word)
                    if not unicodedata.combining(c))
    # A small n-syllable, rather than an arbitrary word containing n.
    syllable = bool(re.fullmatch(r'[^aeiou]*[aeiou]+n+[aeiou]?s?', plain))
    syllable |= bool(re.fullmatch(r'n[aeiou]?|int', plain))
    n = word.count('n')
    if n and word.isalpha():
        if language == 'tr':  # Turkish nasal-bearing morphemes
            if n >= 2 and len(word) <= 5:
                value = 2.0 if word.endswith('n') else 1.6
            elif len(word) <= 3:
                high_vowel = re.search('[iıuü]n', word)
                value = 2.2 if high_vowel and freq[lang] > 4 else 1.3
            elif len(word) <= 5:
                value = .6 if word.endswith('n') else .2
        elif language in ROMANCE:  # Romance languages
            if syllable and len(word) <= 4:
                value = ROMANCE[language]
            elif n >= 2 and len(word) <= 7:
                value = -.8 if language != 'ro' else -1.4
            if space and freq[lang] > 4.5:
                value *= max(0., (6 - freq[lang]) / 1.5)
            if language == 'ro' and word in ROMANIAN_LOCATION_PREPOSITIONS:
                value = -1.7
            if plain.endswith('ion') and n == 1:
                value *= .1
        elif language == 'id' and syllable and len(word) <= 4:
            value = .35
        closed = word.endswith(('ng', 'nt', 'nd', 'ns'))
        if language != 'tr' and closed and word != 'int':
            value *= .1
    if 'ن' in word:
        value = 3.1 if script_bias >= 0 else 1.7
        if len(word) > 3:
            value = .6
        if space:
            value = .6 if len(word) == 1 else 1.1 if len(word) <= 4 else .3
        if len(word) <= 3 and word.startswith(('ا', 'أ', 'إ')):
            value = 2.4 if script_bias >= 0 else 1.4
        # Past-tense copula, versus the common prepositions 'from'/'about'.
        if word.startswith('كان') and len(word) <= 5:
            value = 2.8
        if word in ('من', 'عن'):
            value = .2
    elif word and len(word) <= 2 and not space:
        if previous.endswith('ن'):
            value = 4.0 if word == 'ّ' else 1.0
        elif 'ن' in previous[-2:]:
            value = 1.2 if word == 'ّ' else .4
    if position == 1 and previous == 'Title' and token == ':':
        value = -7.529
    if len(word) >= 2 and set(word) == {'·'}:
        value = -2.26
    return (doc, scores, token, position + 1, script_bias), float(value)

