"""Layer 1, MLP down-projection, component 688.

What it responds to, in plain terms:

1. Location/time prepositions. "at" is strongest, then "in", "on" (and their
   counterparts "en", "в", "на", "при", "auf"). The preposition is weaker or silent
   after idiomatic verbs ("result in", "interested in", "look at"), and stronger
   after biographical verbs ("born in", "educated at", "founded in", "built in").

2. Chinese/Japanese characters (single-character tokens). Positive, and most
   positive when the character opens a new phrase: after punctuation, a space or
   newline, or a grammatical particle (的, を, に, が, 是, 在 ...). Weaker after a
   digit or inside a run of Chinese characters. The very common particles 的, 了, 这
   are near zero.

3. Byte pieces of a Chinese character that the tokenizer splits: the piece that
   completes the character is moderately positive, the first piece is slightly
   positive, and a middle piece is negative.

Everything else (English words, punctuation, digits) predicts 0. The program reads only
the current token, the one before it, and the decoded text so far, so it is causal.
"""

import unicodedata

READS = ()

# Prepositions of place or time, with their typical strength.
PREP_VALUE = {" at": 0.75, " At": 0.9, " in": 0.4, " In": 0.45, " on": 0.4, " en": 0.5,
              " в": 0.8, " на": 0.7, " при": 1.0, " auf": 0.5, " upon": 0.5}
BIRTH_VERBS = {" born", " educated", " founded", " built", " died", " lived", " released",
               " formed", " located", " success", " election", " found"}
IDIOM_VERBS = {" result", " resulting", " interested", " look", " looking", " looks", " looked",
               " aimed", " included", " contained", " engaged", " put"}

# Grammatical particles that open a new phrase, and very common characters that do not.
PARTICLES = set("的をにがは在和是与被把将从对")
FUNCTION_CHARS = set("的了这")

BROKEN = "�"  # how a byte piece of a multi-byte character decodes alone


def is_cjk_char(s):
    return len(s) == 1 and "CJK UNIFIED" in unicodedata.name(s, "")


def cjk_value(s, prev):
    """A Chinese character's strength, by what came just before it."""
    if s in FUNCTION_CHARS:
        return 0.0
    if prev in PARTICLES:
        return 1.2
    if prev.strip() == "" or (not is_cjk_char(prev) and not prev.isdigit() and BROKEN not in prev):
        return 1.0  # opens a new phrase after punctuation or a word
    if prev.isdigit():
        return 0.3
    if is_cjk_char(prev):
        return 0.5  # inside a run of Chinese characters
    return 0.7


def preposition_value(s, prev):
    """An in/at/on-type preposition's strength, by the word before it."""
    if prev in BIRTH_VERBS:
        return 1.1 if s.strip() in ("at", "At") else 0.9
    if prev in IDIOM_VERBS:
        return 0.0
    return PREP_VALUE[s]


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if s in PREP_VALUE:
        return None, preposition_value(s, prev)
    if is_cjk_char(s):
        return None, cjk_value(s, prev)
    if s == BROKEN:
        now = prefix.text_prefixes[-1]
        before = prefix.text_prefixes[-2] if len(prefix.text_prefixes) > 1 else ""
        if now.endswith(BROKEN):  # still incomplete: first piece, or a middle piece
            return None, (-0.25 if before.endswith(BROKEN) else 0.15)
        if now and is_cjk_char(now[-1]):  # this piece completes a character
            return None, 0.5
    return None, 0.0

