"""A short-fragment spelling approximation, not a semantic topic detector.

A preceding n-bearing fragment gates a signed score for the continuation.
AY, EE, and bare B are positive; short O+velar/D spellings and longer IF fragments
are negative. Long fragments and fragments inside an already-started word
are discounted. New words and document starts normally receive zero.
Lexical exceptions and other document-initial effects are not modeled.
"""
from functools import lru_cache
from anyascii import anyascii

READS = ()


@lru_cache(maxsize=32768)
def nasal_gain(previous, embedded):
    if not previous.lower().endswith(
        ('n', 'no', 'ne', 'н', 'не', 'ν', 'ñ', 'ノ', 'ン', 'ن')
    ):
        return 0.0
    s = anyascii(previous).strip().lower()
    if s.endswith('n'):
        gain = 0.65
        if len(s) == 1:
            gain += 0.35
        elif len(s) == 2:
            gain += 0.30
        elif len(s) >= 5:
            gain -= 0.40
    else:
        gain = 0.37 if s.endswith(('ne', 'no')) else 0.0
    return max(0.0, gain - 0.35 * embedded)


@lru_cache(maxsize=32768)
def continuation_score(token):
    if not token or token[0].isspace():
        return 0.0
    s = anyascii(token).lower()
    # A plural s does not change the initial spelling pattern.
    stem = s[:-1] if len(s) > 2 and s.endswith('s') else s
    a, b = s[:1], s[1:2]
    score = 0.0
    if stem == 'ay' and token[:1].lower() == 'a':
        score += 5.6
    if s.startswith('ee'):
        score += 2.5
    if s.startswith('ey'):
        score += 0.4
    if a == 'o':
        if b in ('c', 'k', 'x'):
            # C before e/i is not the velar spelling.
            if not (b == 'c' and s[2:3] in ('e', 'i')):
                score -= 3.7
        if b == 'd':
            score -= 1.4
        if len(stem) == 3 and b in ('d', 'k') and stem.endswith('e'):
            score -= 3.5
    if s.startswith('if') and len(stem) >= 3:
        score -= 2.1
    if stem == 'b':
        score += 3.4
    if a == 'e' and b in ('d', 'b'):
        score += 0.8
    if s.startswith('el'):
        score += 0.6
    if s.startswith('un'):
        score += 0.7
    if a == '.' and b.isalpha():
        score += 1.0
    return score * (1.0 if len(stem) <= 3 else 0.15)


def step(carry, prefix, upstream):
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0
    previous, token = prefix.token_strings[-2:]
    prior = ''
    if prefix.position >= 2 and prefix.document_ids[-3] == prefix.document_ids[-2]:
        prior = prefix.token_strings[-3]
    # Literal newline escapes are not n continuations.
    if (previous.endswith('\\n')
            or (previous == 'n' and prior.endswith('\\'))):
        return None, 0.0
    # Conventional N/A: not applicable.
    if previous.strip().lower() == 'n' and token.lower() == '/a':
        return None, 3.8
    embedded = bool(prior) and prior[-1].isalpha() and not previous[:1].isspace()
    return None, nasal_gain(previous, embedded) * continuation_score(token)

