from functools import lru_cache
import regex
from wordfreq import zipf_frequency

READS = ()
ARTICLES = {'a', 'an', 'the'}
PREPOSITIONS = set('of to in for on with at by from as into about over under '
                   'between through after before without within'.split())
AUXILIARIES = set('is are am was were be been being has have had do does did '
                  'will would can could shall should may might must'.split())
CONJUNCTIONS = set('and or but if because when while although than so'.split())
SCRIPT_STRENGTH = {
    'Han': 5.12, 'Hiragana': 4.38, 'Katakana': 6.85,
    'Cyrillic': 2.14, 'Arabic': 4.14, 'Hangul': 6.11,
    'Devanagari': 4.2, 'Greek': 3.70, 'Hebrew': 4.2, 'Thai': 4.63,
}


@lru_cache(maxsize=16000)
def initial_strength(s):
    q = s.strip()
    space = s.startswith(' ')
    if s == '<|endoftext|>':
        return 12.83
    if s.startswith('<|'):
        return 5.85
    if '\ufffd' in s:
        return 3.17
