        value += 0.65 * min(2, s.count('\n'))
        for chars, offset in [('.!?。！？', -1.68), (',;:，；：', -1.07),
                              ('()[]{}', -0.62), ('\'"‘’“”', -0.38),
                              ('#', 2.92), ('/\\', 0.38),
                              ('+-=*<>|&%$^~', -0.17)]:
