import re
import regex

READS = ()
NEAR_EQUATION = regex.compile(r'(?:equation|equations){e<=1}')
# Equation names in French, Spanish, Portuguese, and Italian.
TRANSLATED_EQUATIONS = regex.compile(
    r'(?:équations?|ecuaci(?:ón|ones)|equa(?:ção|ções)|equazion[ei])'
)
MATH_HEADS = {'formula', 'expression', 'relation', 'condition', 'recurrence'}
EQUATION_TYPES = {'differential', 'functional', 'quadratic', 'cubic', 'parametric'}


def singular(word):
    return word[:-1] if word.endswith('s') else word


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        recent, previous, before = b'', '', ''
    else:
        _, recent, previous, before = carry
    token = prefix.token_strings[-1]
    s = token.strip().lower()
    recent = (recent + prefix.token_bytes[-1])[-192:]
    text = recent.decode('utf-8', errors='replace')
    match = re.search(r'[^\W\d_]+\Z', text)
    original = match.group() if match else ''
    word = original.lower()
    base = singular(word)
    value = 0.0

    # Chinese: systems of equations, equations, equality, and unknowns.
    if word.endswith(('方程组', '方程組')):
        value = -7.2
    elif word.endswith(('方程', '方程式')):
        value = -10.7
    elif word.endswith(('等号', '等號', '不等式')):
        value = -4.5
    elif word.endswith('等式'):
        value = -7.5
    elif word.endswith(('未知数', '未知數')):
        value = -3.5
    elif word.endswith('未知'):
        value = -2.0
    # Korean: equation versus formula (also 'official').
    elif word.endswith('방정식'):
        value = -9.0
    elif word.endswith('공식'):
        value = -3.6
    # Russian equation/equality stems, and German equation/comparison.
    elif word.endswith('уравн') and token.strip() == 'н':
        value = -11.0
    elif word.startswith('уравнени') and not previous.startswith('уравнени'):
        value = -10.0
    elif word.endswith('равн') and token.strip() == 'н':
        value = -7.7
    elif base.endswith('gleichung') or word.endswith('gleichungen'):
        value = -9.0 if word in ('gleichung', 'gleichungen') else -5.0
    elif TRANSLATED_EQUATIONS.fullmatch(word):
        value = -11.0
    elif base.endswith('inequation'):
        value = -15.5
    elif base.endswith('equation'):
        if singular(s) == 'equation':
            value = -3.5 if previous in EQUATION_TYPES else -6.1
        elif re.search(r'\\(?:begin|end)\{equations?\Z', text.lower()):
            value = -3.8
        else:
            value = (-4.8 if before in EQUATION_TYPES else
                     -11.0 if original.isupper() else -8.5)
    elif len(word) >= 6 and NEAR_EQUATION.fullmatch(word):
        value = -10.0
    elif base == 'eqn':
        value = -9.8
    elif word == 'eqs':
        value = -7.5
    elif s == 'eq':
        code = (not regex.fullmatch(r'(?:eq)+', word) or
                re.search(r'(?:__|-|\.)eq\Z', text.lower()) or
                'partialeq' in text.lower())
        value = 0.0 if code else -3.3 if token == ' Eq' else -2.4
    elif word.endswith('eq') and token.strip() == 'q':
        if word.endswith('seq'):
            value = 0.0
        elif word.endswith(('leq', 'geq', 'simeq')):
            value = -0.7
        else:
            value = -4.5 if word.endswith('veq') else -2.7
    elif word in ('equat', 'equate', 'equates', 'equated', 'equating'):
        value = -4.2
    elif word == 'equa':
        value = -7.0
    elif word == 'équ' and s == 'qu':
        value = -2.7
    elif word == 'ecu':
        value = -4.0
    elif word == 'inequ' and s == 'qu':
        value = -3.3
    elif word == 'equ' and s in ('equ', 'qu'):
        value = -4.5 if original.isupper() else -0.9
    elif singular(s) == 'reaction':
        value = -1.1
    elif singular(s) in ('unknown', 'inequality') or s == 'inequalities':
        value = -0.6
    elif s in ('relation', 'condition'):
        value = -0.15
    elif s in ('equal', 'equals'):
        value = -0.1
    elif s == '··' and not text.strip('·'):
        value = -2.6
    elif s == 'thức' and previous == 'phương':
        value = 4.1

    # Short phrase continuations, rather than a persistent math-topic flag.
    if singular(previous) in ('equation', 'eqn'):
        if s == 'of':
            value = -4.8
        elif s == 'for':
            value = -3.2
        elif s == 'becomes':
            value = -2.8
        elif s.isdigit() and not token.startswith(' '):
            value = -0.9
    if s == 'for':
        if previous in ('solve', 'solving', 'solved'):
            value = -5.5
        elif singular(previous) in MATH_HEADS:
            value = {'formula': -0.9, 'condition': -0.4}.get(
                singular(previous), -1.8
            )
    if s == 'motion' and previous == 'of' and singular(before) == 'equation':
        value = -4.4
    if s == 'system' and (previous in ('linear', 'recursive') or
                          re.search(r'\bsolv(?:e|ed|ing)\b', text[-60:].lower())):
        value = -2.7
    if s == 'sign' and previous in ('equal', 'equals', 'inequality'):
        value = -3.5
    if singular(s) == 'relation' and previous in ('recurrence', 'recursion'):
        value = -2.2
    return (doc, recent, word, previous), value

"""Sparse lexical responses, chiefly to 次 (next/time) and 季 (season).

Standalone 次 is strong in next/sequence uses, but weak after small counts.
Common compounds have their own strengths.  Byte-split text can fire on the
detached UTF-8 bytes shared by 次 and 欠-family characters.  The remaining
rules cover document-opening markers and middle-dot-only prefixes.
Most tokens are predicted as zero; these rules do not explain small background
fluctuations or every context-dependent change in the lexical responses.
"""
READS = ()
SMALL_NUMERALS = frozenset('零〇一二两兩三四五六七八九十几幾')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    old = b'' if first else carry[1]
    b = prefix.token_bytes[-1]
    s = prefix.token_strings[-1]
    dots_only = (first or carry[2]) and bool(s) and not s.strip('·')
    previous = old.decode('utf-8', 'ignore').rstrip()
    last = previous[-1:]
    value = -0.09 if first else 0.0

    if s == '次':
        if last.isdigit():
            value = 0.65
        elif last and last in SMALL_NUMERALS:
            several_digits = len(previous) > 1 and previous[-2] in SMALL_NUMERALS
            value = 0.6 if several_digits else -0.2
        elif previous.endswith(('屡', '很多', '多少', '每')) or previous in ('N', 'n'):
            value = 0.5
        else:
            value = 6.2 if last in '。、：' or old.endswith(b'\n') else 5.5
    elif s.startswith('其次'):
        value = 5.0
    elif s == '依次':
        value = 3.8
    elif s == '次要':
        value = 4.3
    elif s == '再次':
        value = 2.15
    elif s in ('上次', '下次'):
        value = 2.45 if s == '上次' else 1.45
    elif s in ('本次', '此次', '多次', '次数'):
        value = 0.6
    elif s in ('层次', '批次'):
        value = 1.2 if s == '层次' else 3.0
    elif s.endswith('人次'):
        value = 4.4 if s == '人次' else 2.0
    elif s == '季':
        value = 0.0 if last in '春夏秋冬' else 1.5
    elif s == '季节':
        value = 0.9
    elif s == '々' and last == '次':  # 次々: one after another
        value = 2.75

    # UTF-8 pieces rather than replacement-character spellings.
    combined = old + b
    if b == b'\xac' and old.endswith(b'\xe6'):
        value = 6.5
    elif b == '次'.encode()[-1:] and old.endswith('次'.encode()[:2]):
        value = 7.3
    if dots_only and s == '··':
        value = -1.4
    if first and s == '--':
        value = 2.7
    elif first and s == '\\"':
        value = -2.2
    elif first and s.strip().lower() == 'create':
        value = 1.4 if s.startswith(' ') else (1.7 if s[0].isupper() else 3.1)
    return (doc, combined[-8:], dots_only), value

"""A spelling detector for 'tur', especially at subword boundaries.

Split-off ur and incomplete -atur stems receive large negative values.
Complete familiar words are much weaker, except the mature/maturity family.
Transliteration extends the same rules to accented and Cyrillic spellings.
Letter context modulates the strength; additional suffix pieces retain a
smaller response. Row/document starts and repeated middle dots have offsets.
"""
from functools import lru_cache
import re
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()


@lru_cache(maxsize=20000)
def spelling(text):
    return anyascii(text).lower().replace("'", '')


@lru_cache(maxsize=10000)
def frequency(word):
    return zipf_frequency(word, 'en')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    initial = carry is None or carry[0] != doc
    left, last = ('', '') if initial else carry[1:]
    raw = prefix.token_strings[-1]
    s = spelling(raw)
    w = s.strip()
    prev = left if s[:1].isalpha() else ''
    value = -0.002
    if initial or last == '<|endoftext|>':
        value += 0.22

    if len(raw) >= 2 and set(raw) == {'·'}:
        value += 1.6
    # The same syllable is strongest when its letters straddle tokens.
    elif prev.endswith('t') and w.startswith(('ur', 'iur')):
        value -= 2.35
        if w in ('ur', 'iur'):
            value -= 3.0
        if w.startswith('ural'):
            value += 1.5
        if len(w) > 4:
            value += 1.5
        # Orthographic context immediately to the left of the t.
        before_t = prev[-2:-1]
        if before_t == 'a':
            value -= 4.15
        elif before_t and before_t in 'eiou':
            value -= 0.4
        if before_t == 'l':
            value -= 2.9
        if before_t == 'p':
            value -= 0.7 if prev.endswith('apt') else 3.1
        if before_t in ('c', 'k'):
            value += 0.95 if prev.endswith('ect') else -2.45
        if len(prev) == 1:
            value += 1.55
        value += 0.05 * max(0, frequency(prev + w) - 2)
    elif prev.endswith(('tu', 'du')) and w.startswith('r'):
        value -= 1.3 if prev.endswith('du') else 5.2
    elif prev.endswith('t') and w == 'u':
        value -= 0.55 if raw.lower() == 'u' else 0.7
        if prev.endswith(('at', 'lt', 'kt', 'ct')):
            value -= 2.35
    elif prev.endswith('t') and w.startswith('ir'):
        value -= 0.14
    elif prev.endswith('t') and re.match('u[aeiout]', w):
        value -= 0.5
    elif prev.endswith('d') and w.startswith('ur'):
        value -= 0.57
    elif prev.endswith(('tur', 'ture')):
        value -= 0.4
        if w in ('d', 's', 'is', 'ities'):
            value -= 2.0
    # An intact word is generally much weaker than an unfinished stem.
    elif 'tur' in w:
        if w.startswith(('mature', 'maturity')):
            value -= 4.5
        elif re.search('(turn|turb|turk)', w):
            pass
        elif w.endswith('atur'):
            value -= 2.65 if s[:1].isspace() else 6.7
        elif w.endswith('tur'):
            value -= 2.2
        elif w.startswith(('ature', 'atura', 'aturi')) and frequency(w) < 3:
            value -= 1.9
        elif w.startswith(('ture', 'ulture', 'ultural')) and frequency(w) < 3:
            value -= 2.2
        else:
            value -= 0.11 + 0.22 * min(2, max(0, 4.7 - frequency(w)))
            if w.startswith('cultur'):
                value -= 0.64

    elif w.endswith('tu') and frequency(w) < 3:
        value -= 0.25

    # Retain only the current word, never text from another document.
    text = left + s if s[:1].isalpha() else s
    ending = re.search('[a-z]+$', text)
    left = ending[0][-30:] if ending else ''
    return (doc, left, raw), value

"""Approximate a detector of compact alternatives and parenthetical expansions.

The largest negative values mark 'and/or', optional plural '(s)'/'(es)',
and parenthetical 'e.g.'/'i.e.'.  Optional endings are distinguished from
function arguments by a short, punctuation-based prose/code heuristic.
Dictionary nouns get stronger optional-plural values than verbs.
Most other tokens receive zero.  Only a bounded text tail is remembered.
"""
import re

import wordnet

READS = ()


def prose_word(tail):
    """Return a prose-like final word, or an empty string for code-like text."""
    text = re.split(r'["`]', tail)[-1].rsplit('\n', 1)[-1]
    text = re.sub(r'\$\{[^}]*\}', '', text)  # template-string interpolation
    match = re.search(r'[A-Za-z]+$', text)
    if not match or len(match[0]) < 3:
        return ''
    word = match[0]
    if not (word.islower() or word.istitle()):
        return ''
    before = text[:match.start()]
    if re.search(r'[A-Za-z_]\([^)]*$', before):
        return ''
    if tail.count('`') % 2 and not before.strip():
        return ''
    if before.endswith(('.', '_', '\\', '::')):
        return ''
    if re.search(r'[_={}]|\b(?:def|fn|return|func|const|var)\b', text):
        return ''
    return word.lower()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    value = 0.0

    if token.lower() == '/or' and tail.lower().endswith('and'):
        value = -5.4
    elif token == '/of' and tail.endswith('en'):  # Dutch 'and/or'
        value = -1.0
    elif token in ('(s', '(es'):
        word = prose_word(tail)
        if word:
            pos = wordnet.parts_of_speech(word)
            value = -6.3 if 'noun' in pos else -1.0 if 'verb' in pos else -3.0
        else:
            value = -0.1
    elif token.startswith(')') and tail.endswith(('(s', '(es')):
        ending = '(es' if tail.endswith('(es') else '(s'
        prose = prose_word(tail[:-len(ending)])
        if token == ')':
            value = -4.9 if prose else -0.5
        elif prose:
            value = -0.5
    elif token in ('.g', '.e'):
        initial = 'e' if token == '.g' else 'i'
        if tail.endswith(initial):
            parenthetical = len(tail) > 1 and tail[-2] in '([{'
            if token == '.g':
                value = -2.0 if parenthetical else -0.28
            else:
                value = -1.65 if parenthetical else -0.16

    return (doc, (tail + token)[-100:]), value

"""A multilingual demonstrative detector: 'this', 'these', 'that', etc.

The response is strongest to isolated Chinese and Korean demonstratives.
English 'that' is weak unless its left context suggests pointing rather than
introducing a clause. English demonstratives are suppressed in code and in
quantifier phrases such as 'none of this'. A short byte history also recognizes
words split between tokens. Unrecognized tokens receive zero.
"""
import re
from functools import lru_cache
from wordnet import base_forms

READS = ()

# Inflected demonstratives, grouped by language and typical response strength.
DEMONSTRATIVES = (
    (1.8, 'ce cette ceci cela ça'.split()),
    (2.8, 'cet ces'.split()),
    (2.4, 'este esta estos estas ese esa esos esas esse essa esses essas'.split()),
    (1.7, 'esto eso isto isso aquilo'.split()),
    (1.5, ['questo']),
    (2.3, 'questa questi queste'.split()),
    (0.8, 'это этот эта эту этого этому этом'.split()),
    (1.6, ['эти']),
    (0.8, 'diese dieser dieses diesen'.split()),
    (1.3, ['diesem']),
    (1.1, 'هذا هذه ذلك تلك وهذا وهذه'.split()),
    (1.2, 'đó đây'.split()),
    (-1.0, ['này']),
)
LEXICON = {word: value for value, words in DEMONSTRATIVES for word in words}
PREPOSITIONS = set(
    'in of for at to with on as from into about after before over under'.split()
)
POINTING_CONTEXT = set('if but then maybe what all that'.split())
OBJECT_VERBS = set(
    'use do apply take copy remove get change turn keep call treat '
    'want like need prefer'.split()
)
QUANTIFIERS = set(
    'none all one some any each both either neither most many much'.split()
)
CHINESE = {'这': 6.5, '這': 5.6, '那': 4.0, '哪': 1.7}
ENGLISH = {'this': 0.95, 'these': 1.35, 'that': 0.05, 'those': 0.65}


@lru_cache(maxsize=2048)
def takes_pointed_object(word):
    return word in OBJECT_VERBS or bool(set(base_forms(word)) & OBJECT_VERBS)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old = carry[1] if carry is not None and carry[0] == doc else b''
    raw = prefix.token_bytes[-1]
    recent = (old + raw)[-192:]
    before = old.decode('utf-8', 'ignore')
    text = recent.decode('utf-8', 'ignore')
    token = prefix.token_strings[-1]
    s = token.strip()
    low = s.lower()
    words = re.findall(r'[^\W\d_]+', before.lower())
    prev = words[-1] if words else ''
    value = 0.0

    # Standalone deictic characters; allow UTF-8 characters split across tokens.
    if s in CHINESE:
        value = CHINESE[s]
    elif ('\ufffd' in token and text and text[-1] in CHINESE
          and recent.endswith(text[-1].encode('utf-8'))):
        value = CHINESE[text[-1]]
    elif s in ('在这', '但这'):
        value = 5.1
    elif s in ('这个', '這個', '在这个'):
        value = 0.5
    elif s in ('この', 'その', 'それ'):
        value = 1.45 if s == 'この' else 0.8
    elif s in ('이', '그'):
        boundary = token[0].isspace() or not before or not before[-1].isalpha()
        value = (5.5 if s == '이' else 3.0) if boundary else 0.0
    elif low in ('this', 'these', 'that', 'those'):
        capital = s[0].isupper()
        value = ENGLISH[low]
        if low == 'that':
            if capital:
                value = 0.85
            elif prev in PREPOSITIONS or prev in POINTING_CONTEXT:
                value = 1.05
                if prev in ('if', 'what', 'at'):
                    value = 1.5
            elif takes_pointed_object(prev):
                value = 0.95
            elif before.endswith(','):
                value = 0.5
            elif prev in ('so', 'and', 'now', 'not', 'think', 'hope'):
                value = 0.4
        elif low in ('this', 'these'):
            if prev in ('if', 'but', 'that', 'when', 'although', 'however'):
                value += 0.4
            if prev == 'although':
                value += 0.65
            elif before.endswith(','):
                value += 0.2
            if prev == 'of' and len(words) > 1 and words[-2] in QUANTIFIERS:
                q = words[-2]
                if low == 'this':
                    value = -2.3 if q == 'none' else -1.4 if q == 'all' else -0.6
                else:
                    value = -0.55 if q == 'none' else 0.0 if q == 'all' else 0.8
        # The object-oriented keyword 'this', rather than a pointing word.
        if low == 'this' and not capital:
            if '\t' in token:
                value = -0.5
            elif prev == 'return' or before.endswith(('=', '$', '.', '(', '+', ':')):
                value = -0.2
            elif before and before[-1].isspace() and not before.endswith('\n'):
                value = -0.25
            elif not token[0].isspace():
                value = 0.1
        if low == 'that' and s.isupper():
            value = 0.0
        if capital and not token[0].isspace():
            value -= 0.2
    else:
        match = re.search(r'([^\W\d_]+)$', text)
        word = match[1].lower() if match else ''
        if recent.decode('utf-8', 'replace').endswith('\ufffd'):
            word = ''
        # Romance demonstratives can contract with 'de' or 'em'.
        canonical = word
        if re.fullmatch(r'[dn](?:est[aeo]s?|ess[ae]s?)', word):
            canonical = word[1:]
        if word.startswith(('é', 'á')):
            canonical = word.replace('é', 'e').replace('á', 'a')
        if word in ('این', 'آن'):
            value = 5.8 if word == 'این' else 4.5
        elif canonical in LEXICON:
            value = LEXICON[canonical]
            if s and s[0].isupper():
                value += 0.3
            # Completing a split Romance demonstrative elicits a larger pulse.
            if canonical != low and canonical.startswith(('quest', 'ess', 'est')):
                value = 3.7
            if s.isupper():
                value *= 0.1
            elif not token[0].isspace() and word == low and word.isascii():
                value *= 0.5
            if word == 'đây' and word != low:
                value = 5.0
            if word == 'este' and any(c in before for c in 'ăâîșțşţ'):
                value = -0.5
        elif low in ('bu', 'dies', 'dit', 'deze'):
            # Disambiguate Turkish, German and Dutch from English/French homographs.
            if low == 'bu':
                local = any(c in before.lower() for c in 'ığşçöü')
                local |= bool(set(words) & {'bir', 've', 'için', 'ile', 'olarak'})
                value = 3.2 if local else 0.1
            elif low == 'dies':
                local = bool(set(words) & {
                    'der', 'die', 'das', 'ist', 'und', 'nicht', 'für'
                })
                value = 2.15 if local else 0.1
            else:
                local = bool(set(words) & {
                    'het', 'een', 'van', 'zijn', 'dat', 'niet', 'voor', 'met'
                })
                value = (2.3 if low == 'deze' else 1.7) if local else 0.1
        elif low == 'quest':
            value = 1.7 if token[0].isspace() else 0.3
    return (doc, recent), float(value)

"""A spelling-fragment approximation, not a semantic people/mind detector.

Recognize men/ment and min+d/t fragments in transliteration, with stronger
responses to syllables split at m|ent and to letter-spaced m e n (t).
Word boundaries and a few consonant-cluster rules modulate the response.
Han logographs are excluded. Middle-dot leaders have a separate positive rule.
This omits the weaker spelling effects of the larger training fit.
"""
import re
import regex
from functools import lru_cache
from anyascii import anyascii

READS = ()

STEMS = {
    'men': -1.30,
    'mens': -1.64,
    'ment': -0.92,
    'mental': -0.89,
    'ments': -0.85,
    'mind': -1.62,
    'mint': -0.91,
}
PREFIXED = {
    'ment': 0.57,
    'mind': -0.74,
    'mint': -0.54,
}
WORD_INITIAL = {
    'men': 1.10,
    'ment': -0.80,
    'mental': -0.65,
    'ments': -0.66,
    'mind': 0.89,
}
AFTER_SPACE = {
    'ment': -0.80,
    'mind': 0.40,
}
SPLIT_SYLLABLE = {
    'men': -1.14,
    'men_other': -0.72,
    'mens': -1.60,
    'ment': -4.22,
    'ment_other': -2.23,
    'ments': -4.51,
    'mind': -0.72,
    'mint': -1.72,
}

@lru_cache(maxsize=16384)
def spelling(text):
    return anyascii(text).lower()


def family(vowel, tail):
    if vowel in ('e', 'ie'):
        if tail in ('', 't', 'ts', 'ted', 'tal', 'tally', 's'):
            return 'men' + tail
        return 'ment_other' if tail.startswith('t') else 'men_other'
    if vowel == 'i':
        if tail.startswith('d'):
            return 'mind'
        if tail.startswith('t'):
            return 'mint'
    return ''


def response(previous, text, history):
    value = 0.00074
    if len(text) >= 2 and set(text) == {'·'}:
        value += 1.87
    s = spelling(text).strip()
    p = spelling(previous).rstrip()
    if not s or regex.search(r'\p{Script=Han}', text):
        return value
    inside_word = bool(p and p[-1].isalpha() and not text[:1].isspace())
    match = re.search(r'm([aeiouy]+)[nm]', s)
    if match and (match.start() <= 1 or (match.start() <= 3 and inside_word)):
        kind = family(match[1], s[match.end():])
        value += STEMS.get(kind, 0.0)
        if match.start():
            value += PREFIXED.get(kind, 0.0)
        if not inside_word:
            value += WORD_INITIAL.get(kind, 0.0)
        if text[:1].isspace():
            value += AFTER_SPACE.get(kind, 0.0)
        if inside_word and kind == 'men' and p[-1] in 'nrl':
            value += 0.51
        if inside_word and re.search(r'[nm][ptk]$', p):
            if kind == 'men':
                value -= 1.09
            elif kind == 'ment':
                value -= 0.53
    if inside_word and p.endswith('m'):
        match = re.match(r'([aeiouy]+)n', s)
        if match:
            value += SPLIT_SYLLABLE.get(family(match[1], s[match.end():]), 0.0)
    joint = spelling(history + previous).rstrip()
    if s.startswith('n') and re.search(r'm\s+e\s*$', joint):
        value -= 2.79
    if s.startswith('t') and re.search(r'm\s+e\s+n\s*$', joint):
        value -= 3.92
    if inside_word and s.isalpha() and len(s) <= 4 and s.startswith('t'):
        if re.search(r'm[aeiouy]+n$', joint):
            value -= 1.0
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        history, previous = '', ''
    else:
        _, history, previous = carry
    text = prefix.token_strings[-1]
    value = response(previous, text, history)
    return (doc, (history + previous)[-40:], text), float(value)

"""Sparse lexical detector for Chinese wishes, invitations and exhortations.

Blessings (祝, 'wish/bless') are strongest, followed by 'let us', welcomes,
requests and hopes. Washing and several concrete operations have the opposite
sign. Small extra rules cover shell names and document starts.
These are lexical cues, not a complete semantic analysis of a sentence.
"""
import codecs
import regex as re
from functools import lru_cache
import opencc

READS = ()
_converter = opencc.OpenCC('t2s')


@lru_cache(maxsize=8192)
def simplified(text):
    return _converter.convert(text)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    recent, pending = ('', b'') if start else carry[1:]
    data = pending + prefix.token_bytes[-1]
    raw, used = codecs.utf_8_decode(data, 'replace', False)
    pending = data[used:]
    text = simplified(raw)
    token = text.strip(' ，。！？、\n\t')
    context = recent + text
    japanese = bool(re.search(r'\p{Script=Hiragana}|\p{Script=Katakana}', recent))
    value = 0.0

    if token == '祝':
        value = 3.8 if japanese else 6.2
    elif token in {'愿', '祝愿'}:
        value = 3.0
    elif token == '祝福':
        value = 2.6
    elif context.endswith('让我们') and token:
        value = 2.4
    elif token in {'欢迎', '欢迎大家', '欢迎您', '欢迎你'}:
        value = 1.25
    elif token in {'请', '敬请'}:
        value = 0.85 if raw.startswith('，') else 1.05
        if recent.endswith('声'):
            value = 0.2  # 声请 means an application, not 'please'.
    elif token in {'希望', '希望大家', '希望你', '希望我们'}:
        value = 0.5
    elif token in {'让你', '让我', '愿意'}:
        value = 0.7
    elif token in {'让', '快来', '不如'}:
        value = 0.3
    elif token in {'大家', '各位', '你们'}:
        value = 0.35
    elif token == '洗':
        value = -0.8 if japanese else -1.8
    elif token in {'剪', '切割', '划分', '打印', '拆', '煮', '煎', '浇水'}:
        value = -0.6
    elif token in {'创建', '构建', '安装', '合并', '点击', '摆放', '摇', '搬'}:
        value = -0.4
    elif token == '定义':
        value = -0.2
    elif token == 'bash':
        value = 0.24
    elif token == 'ash' and recent.endswith('b'):
        value = 0.51
    if token in {'你', '您'} and recent.endswith('祝'):
        value = 2.5
    if start and value == 0.0:
        # Broad surface categories, not a table of first-token identities.
        if raw.startswith('<|'):
            value = -0.17
        elif raw.isspace():
            value = -0.14
        elif raw.strip() in {'"', "'", '“', '‘'}:
            value = -0.45
        elif raw.strip() == '.':
            value = 0.19
        elif re.fullmatch(r'\s*[A-Z][A-Za-z]*', raw):
            value = -0.25
        elif re.fullmatch(r'\s*[a-z]+', raw):
            value = -0.11
        else:
            value = -0.04
    return (doc, context[-40:], pending), value

programs.haiku:
"""Layer-1 MLP down-projection component 702: a "wish / invite / let us" detector.

In plain terms, this component reads the current word and writes a signed amount:
- Strongly positive on the Chinese word for "wish" (祝 "wish", 祝福, 祝愿).
- Weakly positive on 愿 and 願 ("may, wish").
- Positive on words that open an invitation or request to people: 让我们 "let us"
  (the largest of these), 欢迎 "welcome", 请 "please", 让你 "let you", 陪, and the
  figure-of-speech words 比喻, 寓, 形容, 喻.
- Mildly positive on words that address a group: 让 "let", 希望 "hope", 大家, 你们,
  各位 "everyone", 愿意, 加油.
- Negative on hands-on or technical action verbs: 洗 "wash" (most negative),
  切割 "cut", 搬 "move", 拆 "take apart", 煮 "cook", 安装 "install", 创建 "create",
  点击 "click", 显示 "display", 打印 "print", 定义 "define", and similar.
- Slightly positive on the shell name "bash" inside tool calls.
- A document's first token (the start of a row, or right after <|endoftext|>) has
  no earlier context, so its value is set by the token alone: Latin capitalised
  words there are about -0.3, lower-case words about -0.15.
Every other token predicts 0.

The table is a short list of common words, grouped by meaning. Most of the
variance is spread over many tokens, so this captures only part of it.
"""

import re

from collections.abc import Mapping

READS = ()

WISH = {"祝", "祝福", "祝愿"}
WANT = {"愿", "願"}
LET_US = {"让我们"}
INVITE = {"欢迎", "歡迎", "请", "，请", "請", "让你", "让我", "陪", "形容", "比喻", "寓", "喻"}
ADDRESS = {"让", "讓", "希望", "大家", "你们", "你們", "各位", "愿意", "加油"}
WASH = {"洗"}
ACTION = {"清洗", "删", "切割", "策划", "划", "搬", "拆", "构造", "定位", "煮", "煎",
          "添加", "安装", "定义", "显示", "确认", "准备", "安排", "创建", "点击", "打印"}
SHELL = {"ash", "bash"}


def word_value(word):
    """The signed amount a single token's text sets, from its meaning group."""
    if word in WISH:
        return 5.0
    if word in LET_US:
        return 2.5
    if word in WANT:
        return 1.5
    if word in INVITE:
        return 1.2
    if word in ADDRESS:
        return 0.35
    if word in WASH:
        return -1.5
    if word in ACTION:
        return -0.5
    if word in SHELL:
        return 0.3
    return 0.0


def step(carry, prefix, upstream: Mapping):
    word = prefix.token_strings[-1].strip()
    first = len(prefix.document_ids) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if first:
        if re.fullmatch(r"[A-Z][a-z]+", word):
            return carry, -0.3
        if re.fullmatch(r"[a-z]+", word):
            return carry, -0.15
        return carry, 0.0
    return carry, word_value(word)
